export default [{"id":189,"question":"رجلٌ متزوج وعنده أولاد، ويسكن مع والده وإخوانه، هل تكفيهم أضحيةٌ واحدةٌ؟","title":"هل تجزئ أضحية واحدة عن أهل بيت واحد؟","answer":"الجواب: نعم، ولو كانوا مئةً، تكفيهم أضحيةٌ واحدةٌ، إذا كانوا مُجتمعين: أب وعياله، عشرة، عشرين، وزوجاتهم، تكفيهم واحدة، وإن ذبحوا ثنتين أو ثلاثًا أو أكثر فلا بأس، لكن تكفيهم واحدةٌ في فعل السنة، فالنبي ﷺ عنده تسع نساء، وكان يُضحِّي بواحدةٍ عنه وعن أهل بيته عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/3762/هل-تجزى-اضحية-واحدة-عن-اهل-بيت-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0193.mp3","categories":["الهدي والأضاحي"]},{"id":350,"question":"سماحة الشيخ يسلم منذ سنوات توزيع الأضحية إلى ثلاثة أقسام: يوزع قسمٌ منها على الفقراء والمساكين، ونطبخ الثلثين الآخرين في المنزل، ونجتمع عليها مع الأقارب، هل علينا في ذلك شيءٌ؟ نرجو التوضيح جزاكم الله عنا وعن المسلمين خير الجزاء.","title":"ما المشروع في توزيع الأضحية؟","answer":"الجواب: الأضحية شرعها الله لعباده ، وجعلها قربةً يتقرب بها إليه في عيد النَّحر، في الحاضرة والبادية، ولم يُحدد سبحانه ما يأخذه منها صاحبها، وما يُعطيه الفقراء، فقال : فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ الْفَقِيرَ [الحج:28]، والآية الأخرى: فَكُلُوا مِنْهَا وَأَطْعِمُوا الْقَانِعَ وَالْمُعْتَرَّ [الحج:36].\nفالمشروع للمؤمن في ضحيَّته أن يأكل ويُطعم، فإذا أخرج الثلث ووزعه للفقراء وأكل الثلثين مع أهل بيته؛ فلا بأس ولا حرج في ذلك، ولو أخرج أقلَّ من الثلث؛ كفى ذلك، وإن أعطى الفقراء أيضًا من جيرانه وأقاربه؛ فلا بأس، فالأمر في هذا واسعٌ، والحمد لله.","link":"https://binbaz.org.sa/fatwas/4439/ما-المشروع-في-توزيع-الاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0403.mp3","categories":["الهدي والأضاحي"]},{"id":491,"question":"قول ابن العربي في شرح الترمذي: ليس في فضل الأضحية حديث صحيح؟","title":"هل صح حديثٌ في فضل الأضحية؟","answer":"الجواب: ما أذكر   شيئًا صحيحًا فيها، مثل ما قال، إنما هي من فعل النبي ﷺ وأمره، وليس فيها \"فله كذا وكذا.. أجر على عدد الشعر\" هذا حديث ضعيف.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6266/هل-صح-حديث-في-فضل-الاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/maram054 - 02 - .mp3","categories":["الهدي والأضاحي"]},{"id":492,"question":"إذا كان في بَرِّيَّة متى يذبح أضحيته؟","title":"ما وقت ذبح الأضحية لمن كان في بَرِّيَّة؟","answer":"الجواب: إذا ارتفعت الشمس.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6267/ما-وقت-ذبح-الاضحية-لمن-كان-في-برية","audio":"https://files.zadapps.info/binbaz.org.sa/maram055 - 02 - .mp3","categories":["الهدي والأضاحي"]},{"id":493,"question":"هل عليه أن ينوي ببداية ذي الحجة؟ مثلا ًشخص قرر في خمسة ذي الحجة أن يضحي؟","title":"متى وقت الكف عن الشعر والظفر للمضحّي؟","answer":"الجواب: متى ما نوى الأضحية لا يأخذ شيئًا من شعره ولا من أظفاره.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6268/متى-وقت-الكف-عن-الشعر-والظفر-للمضحي","audio":"https://files.zadapps.info/binbaz.org.sa/maram056 - 02 - .mp3","categories":["الهدي والأضاحي"]},{"id":494,"question":"هل ثبت عن النبي ﷺ أن جمع بين الهدي والأضحية؟","title":"هل ثبت بالسُّنة الجمع بين الهدي والأضحية؟","answer":"الجواب: هو الظاهر أهدى بحجة الوداع مائة بدنة وضحى بكبشين.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6270/هل-ثبت-بالسنة-الجمع-بين-الهدي-والاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/maram057 - 02 - .mp3","categories":["الهدي والأضاحي"]},{"id":495,"question":"دفع قيمة الأضحية إلى بلد محتاج؟","title":"حكم دفع قيمة الأضحية لبلد محتاج","answer":"الجواب: لا، الأضحية أفضل، يضحي ولا يدفع الثمن.\n(دروس شرح بلوغ المرام، كتاب الاطعمة)","link":"https://binbaz.org.sa/fatwas/6271/حكم-دفع-قيمة-الاضحية-لبلد-محتاج","audio":"https://files.zadapps.info/binbaz.org.sa/maram058 - 02 - .mp3","categories":["الهدي والأضاحي"]},{"id":496,"question":"تقسيم الأضحية إلى أثلاث؟","title":"هل يلزم تقسيم الأضحية على أثلاث؟","answer":"الجواب: هذا اختيار جماعة من أهل العلم، والأمر واسع إن شاء الله؛ يوزعها أثلاثًا أو أرباعًا أو وزعها كلها، يوزع ما تيسر ولو قليل؛ لأن الله قال: فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ[الحج:28]\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6272/هل-يلزم-تقسيم-الاضحية-على-اثلاث","audio":"undefined","categories":["الهدي والأضاحي"]},{"id":497,"question":"إذا اشتريت أضحية خالية من العيوب ثم كسرت قرنها أو قطعت أذنها بدون تفريط مني هل تجزئ أم لا؟","title":"ما حكم العيب الطارئ بعد شراء الأضحية؟","answer":"الجواب: الظاهر أنها تعينت وتجزئ إن شاء الله.\n(دروس شرح بلوغ المرام، كتاب الاطعمة)","link":"https://binbaz.org.sa/fatwas/6275/ما-حكم-العيب-الطارى-بعد-شراء-الاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/maram061  - 02 - .mp3","categories":["الهدي والأضاحي"]},{"id":498,"question":"قوله: \"ألا نضحي بعوراء ولا مقابلة ولا مدابرة\" للكراهة أو للتحريم؟","title":"حكم التضحية بالعوراء والمقابلة والمدابرة","answer":"الجواب: العوراء حديث البراء صريح فيها، أما البقية تُكره.\n(دروس شرح بلوغ المرام، كتاب الاطعمة)","link":"https://binbaz.org.sa/fatwas/6276/حكم-التضحية-بالعوراء-والمقابلة-والمدابرة","audio":"https://files.zadapps.info/binbaz.org.sa/maram062 - 02 - .mp3","categories":["الهدي والأضاحي"]},{"id":504,"question":"هل شروط الأضحية والعقيقة والهَدْي سواء؟","title":"هل شروط الأضحية والعقيقة والهَدْي سواء؟","answer":"الجواب: نعم، سواء، لا يجزي فيها إلا في الأضاحي، لا في الهدي ولا في العقيقة، لا يجزي فيها إلا ما يجزي في الأضاحي.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6283/هل-شروط-الاضحية-والعقيقة-والهدي-سواء","audio":"undefined","categories":["الهدي والأضاحي","أحكام المولود"]},{"id":695,"question":"أريد أن أتمتع بالحج في العام القابل بإذن الله، ولكن إذا أردتُ أن أُضحي عني وعن أهلي فهل يُجزئ هَدْي الحج؟","title":"هل تجزئ الأضحية عن هَدْي الحج؟","answer":"الجواب: الهَدْي غير الضَّحية بارك الله فيك، فالهدي شيءٌ، والضَّحية شيءٌ، الهدي عن التَّمتع، والضَّحية مُستحبَّة للجميع وإن لم يحجّ، مُستحبَّة لجميع الناس، في الحضر والبدو، والقرى والأمصار، الضَّحية واحدةٌ عن الرجل وأهل بيته.\nكان الرسول ﷺ يُضحِّي بكبشين عنه وعن أهل بيته وعن أمة محمدٍ ﷺ، كل سنة يُضحِّي بكبشين أملحين أقرنين: أحدهما يذبحه عن نفسه وأهل بيته، والثاني عمَّن وحَّد الله من أمته عليه الصلاة والسلام.\nفالسنة لك يا عبدالله أن تُضحي بواحدةٍ عنك وعن أهل بيتك: زوجتك وعيالك ووالديك، وإن ضحّيتَ بثنتين أو ثلاث فلا بأس، لا تدعها إن كنتَ قادرًا، أما إن كنتَ عاجزًا: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لكن مع القُدرة هي سنة غير واجبةٍ، لكنها سنة.","link":"https://binbaz.org.sa/fatwas/19887/هل-تجزى-الاضحية-عن-هدي-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0190.mp3","categories":["الهدي والأضاحي"]},{"id":698,"question":"يقول: إنه اعتمر لوالده في شوال الماضي، وسيقوم بالحج لنفسه هذا العام إن شاء الله، وأخبره البعضُ بأنَّ عليه دمًا، والبعض الآخر أخبره بأنه لا يجب عليه دمٌ، فما الحكم في ذلك؟","title":"ما ضابط وجوب الدم على من حج متمتعًا؟","answer":"الجواب: إذا اعتمرتَ لوالدك في شوال، أو في ذي القعدة، أو لغير وارثٍ من الأموات، ثم حججتَ عليك دمٌ؛ لأنك تصير متمتعًا، سواء كان الحج لك والعمرة لغيرك، أو العمرة لك والحج لغيرك، كله واحد، أو لك الحجّ والعمرة جميعًا، فأنت متمتع، فعليك الهدي، إلا أنك إذا ذهبتَ إلى أهلك بعد العمرة -ذهبت إلى بلادك- ثم أتيتَ بحجٍّ مفردٍ؛ فالجمهور يرون أنه لا شيء عليك، جاء عن عمر وابنه: أنَّ المتمتع إذا رجع إلى أهله ثم جاء بحجٍّ مفرد فلا شيء عليه، وجاء عن ابن عباسٍ رضي الله عنهما: أنَّ عليه الهدي ولو رجع إلى أهله، وهو القول المشهور عن ابن عباسٍ، فإذا أهدى ولو رجع إلى أهله يكون أحوط وأحسن، والجمهور على أنه لا يجب عليه إذا رجع إلى أهله.","link":"https://binbaz.org.sa/fatwas/20551/ما-ضابط-وجوب-الدم-على-من-حج-متمتعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0512فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["الهدي والأضاحي"]},{"id":1195,"question":"بعض الناس يُرسل الأضحية أو العقيقة إلى بعض البلاد عن طريق أشخاصٍ أو المصارف، مُخالفين السنة النبوية، ما تعليق سماحتكم على ذلك؟","title":"حكم إرسال الأضحية أو العقيقة خارج بلدها","answer":"الجواب:\nالأفضل أن يذبح العقيقة في بيته، العقيقة يعني: نسيكة الولد، وهي شاتان عن الذكر، وشاة واحدة عن الأنثى، تُسمَّى: عقيقة، وتُسمَّى: تميمة، يُسميها بعض الناس: تميمة، وتُسمَّى: نسيكة، وهي سنة مؤكدة، والرسول ﷺ أمر أن يعقَّ عن الغلام شاتان، وعن الجارية شاة، وتُذبح يوم السابع. هذا هو الأفضل، يذبحها المسلمُ في بيته يوم السابع، ويأكل منها، ويُطعم مَن شاء من جيرانٍ وأقارب وغيرهم، أو يُوزِّعها، يتصدَّق ويُوزِّعها، ولا يُوزِّعها للخارج، الأفضل في بيته، يأكل منها، ويُطعم منها. ولو أرسلها إلى الخارج -إلى المجاهدين أو غير المجاهدين- بيد وكيلٍ ثقةٍ يذبحها هناك ويُوزِّعها؛ فلا بأس، ولكن كونه يذبحها في بيته وبين أهله، ويُحْيُون السُّنة، ويُظهرون السُّنة بينهم وبين جيرانهم، ويأكلون ويُطعمون؛ هذا هو الأفضل، وهو السُّنة.","link":"https://binbaz.org.sa/fatwas/21237/حكم-ارسال-الاضحية-او-العقيقة-خارج-بلدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1157بعض الناس يرسل أضحيته أو العقيقةخارج البلاد فما الحكم؟ ابن باز فتاوى.mp3","categories":["الهدي والأضاحي","أحكام المولود"]},{"id":1196,"question":"تسأل عن أضحية والدها تقول: إني اضطررتُ أن أمشط شعري قبل أن تُذبح الضحية، هل عليَّ من شيءٍ؟","title":"ماذا يجب على من أراد أن يُضَحِّي؟","answer":"الجواب:\nإذا عزم المسلمُ أو المسلمة على الضَّحية بعد دخول شهر ذي الحجة، سواء الضحية لنفسها أو لها أو لأهل بيتها أو لأبيها أو لأمها، إذا عزمت على الضحية لا تأخذ من شعرها ولا من أظفارها شيئًا، وهكذا الرجل إذا عزم على الضحية لنفسه أو لأهل بيته أو لأبيه أو لأمه لا يأخذ من شعره ولا من أظفاره شيئًا. والسنة واحدة، تكفيه عنه وعن البيت جميعًا ضحية واحدة، يذبحها عنه وعن أهل بيته وأبيه وأمه جميعًا، تكفي، وإن ضحَّى بأكثر فلا بأس، لكن لا يأخذ من شعره ولا من أظفاره ولا من جلد بشرته شيئًا بعد دخول الشهر حتى يُضَحِّي.\nأما كونها تُمشّط رأسها لا بأس، المشط لا بأس به، تنفضه وتمشطه لا بأس، لكن لا تخده بالمكد -لا تقطعه بالمكد- إنما تنقضه وتمشطه، ولو سقط شيء ما يضرُّ؛ لأنَّ الساقط شعرٌ ميتٌ لا يضرُّ إذا سقط، لكن لا تتعمد قطعه ولا كدّه بالمكد، أما كونها تنقضه وتغسله وتمشطه لا بأس، ولو كان ضحيةً؛ لأن الرسول صلى الله عليه وسلم أمر عائشة وهي مُحرمة أن تُمشط رأسها لما حاضت، وأن تُحرم بالحج.\nس: هذا الأمر يعني: أبو العائلة لوحده مثلًا، أو العائلة كلهم؟\nالشيخ: إذا ذبح واحدةً سدَّ عنهم كلهم، عنه وعن أهل البيت: الأولاد وزوجته، ولو هم مئة ضحية واحدة تكفي عنهم.\nس: لكن يلتزمون كلهم...؟\nالشيخ: لا، فقط هو الذي يمتنع، هو.\nس: هو فقط؟\n الشيخ: الذي يُضحِّي هو الذي يمتنع، أما عائلته وأولاده ما عليهم شيء.\n..... إذا كانوا بيتًا واحدًا الضَّحية الواحدة تكفي، أما إذا كانوا في بيوتٍ، كل واحدٍ له بيتٌ مُستقلٌّ؛ فكلٌّ يُضحِّي عن نفسه.","link":"https://binbaz.org.sa/fatwas/21236/ماذا-يجب-على-من-اراد-ان-يضحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1158أذا أراد المسلم أن يضحي فما يجب عليه؟ ابن باز فتاوى.mp3","categories":["الهدي والأضاحي"]},{"id":1617,"question":"يقول سائلٌ: والدتي تُقيم وحدها في مدينةٍ بعيدةٍ عن الرياض، وسوف أقضي عيد الأضحى معها إن شاء الله تعالى أنا وزوجتي وابنتي، فهل يكفي أضحية واحدة عني وعن أهلي وعن والدتي، أم لا بدّ أن يكون لكلٍّ منا أضحية؟ علمًا بأني قادر على شراء أي عددٍ.","title":"هل تُسَنُّ أضحية خاصة لمن كان يقيم بمفرده؟","answer":"الجواب:\nإذا كانت أمك في بيتٍ لحالها تُسنّ لها أضحية وحدها، وأنت تُضحي عن نفسك وأهل بيتك، فما دامت أمك مستقلةً في بيتٍ لها فالأفضل لها أن تُضحي إذا قدرت، وأنت تُضحي وأهل بيتك، وإذا انتقلتَ إليها وذبحتَ الضَّحيةَ عندها حصل خيرٌ إن شاء الله.\nس: إذا صار عنده خدمٌ هل يُشركهم في أضحيته؟\nج: ما هو بلازم، أهل بيته: زوجته وأولاده.\nس: الخدم ما يدخلون؟\nج: لا، هذا من باب الإحسان إليهم، فهم أُجَرَاء.","link":"https://binbaz.org.sa/fatwas/21721/هل-تسن-اضحية-خاصة-لمن-كان-يقيم-بمفرده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من كان مستقلا بنفسه يسن له أضحية مستقلة.mp3","categories":["الهدي والأضاحي"]},{"id":1727,"question":"الحاج إذا كان عليه هديٌ -كالمُتمتِّع والقارن- ولا يُريد الأضحية، فهل يجب عليه أن يُمسك عن شعره؟","title":"حكم الحاج الذي عليه هَدْي ولا يريد الأضحية","answer":"الجواب:\nلا، ما يُمسك.","link":"https://binbaz.org.sa/fatwas/21834/حكم-الحاج-الذي-عليه-هدي-ولا-يريد-الاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يمسك الحاج الذي عليه هدي ولا يُريد الأضحية هل يجب عليه أن يُمسك عن شعره.mp3","categories":["الهدي والأضاحي"]},{"id":1731,"question":"اشترك مجموعةُ فقراء في أضحيةٍ فهل يُمسكون جميعًا (عن أخذ الشعر)؟","title":"حكم أخذ الشعر للمشتركين في أضحية؟","answer":"الجواب:\nما أعرف لهذا أصلًا، إلا إذا كانوا سُكَّان بيتٍ واحدٍ فلا بأس.\nس: هم في منزلٍ واحدٍ، لكنَّهم ليسوا إخوانًا؟\nج: إذا كانوا سكَّان بيتٍ واحدٍ فلا بأس، كلهم يُمسكون عن أخذ الشعر والظفر، أو رفقة في السفر كالبيت الواحد.\nس: هل يُشترط أن يكونوا من نفس العائلة؟\nج: إذا كانوا من بيتٍ واحدٍ ولو أجانب؛ لأنهم صاروا أهل بيتٍ، وفي الحديث: تُجزئ عن الرجل الضحية عنه وعن أهل بيته.","link":"https://binbaz.org.sa/fatwas/21838/حكم-اخذ-الشعر-للمشتركين-في-اضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا اشترك مجموعة في أضحية فهل يمسكون جميعا.mp3","categories":["الهدي والأضاحي"]},{"id":1942,"question":"الأضحية على الأموات؟","title":"حكم الأضحية عن الأموات وتخصيصهم بها","answer":"الجواب:\nداخلة في العموم، تعمّها الأحاديث، إذا ضحَّى عنه وعن أهل بيته يعمّها.\nس: تخصيصهم بالأُضحية؟\nج: لا مانع؛ لأنها صدقة، الضحية صدقة.\nس: مَن قال أنها بدعة؟\nج: لا، ما عنده خبر؛ لأنها صدقة ومساعدة وتقرّب إلى الله جل وعلا بالذبح.\nس: تدخل في باب الصَّدقة؟\nج: نعم، والنبي ﷺ ضحَّى بالضحية عنه وعن أهل بيته، وأهل بيته فيهم الميت وفيهم الحي، فيهم خديجة ميتة، وفيهم بعض بناته عليه الصلاة والسلام.\nس: تخصيص الأموات؟\nج: إذا خصَّهم لا بأس، كان النبيُّ ﷺ كثيرًا ما يُضَحِّي بذبح الشاة عن خديجة، يتصدق بها عن خديجة، ويقسمها بين صواحبات خديجة بعد وفاتها رضي الله عنها.","link":"https://binbaz.org.sa/fatwas/22055/حكم-الاضحية-عن-الاموات-وتخصيصهم-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الإضحية عن الأموات وتخصيصهم بها.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":1945,"question":"بالنسبة ليوم عرفة: هل ورد فيه شيء من الأُضحية؟ يعني: يُخْرِج شاةً أو شاتين.","title":"هل ليوم عرفة أضحية؟","answer":"الجواب:\nيوم عرفة ما فيه أضحية، الأضحية يوم العيد وأيام العيد.\nس: بعض العامَّة يذبحون في يوم عرفة؟\nج: يوم عرفة يُصام، فالذي يريد أن يصوم فليَصُمْ، فالصيام فيه سُنة، إلا الحُجَّاج لا يصومون.","link":"https://binbaz.org.sa/fatwas/22059/هل-ليوم-عرفة-اضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ليوم عرفة أضحية.mp3","categories":["الهدي والأضاحي"]},{"id":3787,"question":"لو أخرجها من الحرم كلها، لو كانت لحومًا كثيرة وأخرجها كلها؟","title":"حكم إخراج الهدايا والضحايا من الحرم؟","answer":"الجواب: العمل في البنك الإسلامي الآن وُسِّع، جاءتهم فتوى من هيئة كبار العلماء، يوزع في الخارج من الهدايا والضحايا. س: لو لم يوزع منها شيء في الحرم، بأكملها أخرجت من الحرم؟ ج: يُوزع منها ما تيسر هنا وهناك، وإن أُخرجت كلها لا بأس، لو أعطاها الفقراء أو أكلها، بعضُ أهل العلم يرى وجوب بعض الشيء اليسير في الضَّحية.\nس: إذا أخرجها كلها من الحرم، كانت كثيرة مثلًا ووُزعت كلها على الفقراء خارج الحرم؟\nج: ما نعلم فيه مانعًا، إلا إن كان فقراء الحرم محتاجين؛ يُبدأ بهم.","link":"https://binbaz.org.sa/fatwas/23985/حكم-اخراج-الهدايا-والضحايا-من-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هدايا وضحايا الحرم إذا أخرجت خارج الحرم.mp3","categories":["الهدي والأضاحي"]},{"id":3819,"question":"البادية ما عندهم صلاة؟","title":"متى يذبح أهل البوادي والمسافرون الأضاحي؟","answer":"الجواب: تقدم البحث في هذا، وأن العلماء اختلفوا: فمنهم مَن قال في حقِّهم من طلوع الفجر... أهل منى في الهدايا والأضاحي.  وقال آخرون: بعد ارتفاع الشمس قيد رمح، وهو مضي قدر الصلاة، يعني بتقدير الإنسان إذا ارتفعت الشمسُ ومضى قدرُ الصلاة ذبح البوادي والمسافرون وأهل منى.  فالأحوط في هذا مثل ما قال بعضُ أهل العلم: يتأخَّر حتى تطلع الشمس، ترتفع، يمضي قدر الصلاة، ثم يذبح، وإن ذبح في أول النهار لأنَّ الرسول عليه الصلاة والسلام لما سُئل قالوا له: يا رسول الله، نحرتُ قبل أن أرمي؟ يعني يوم العيد، قال: لا حرج، ولم يقل له: هل نحرتَ قبل الشمس أو بعد الشمس؟ فيدل ذلك على أن الأمر يوم العيد عام لمن ليس عندهم صلاة يوم العيد، يوم الأضاحي، لو كان فيه تفصيل لسأله وقال: هل ذبحتَها قبل الشمس أو بعد الشمس؟ لكن مَن كان عنده صلاة فالحكم مربوط بالصلاة.","link":"https://binbaz.org.sa/fatwas/24020/متى-يذبح-اهل-البوادي-والمسافرون-الاضاحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يذبح أهل البوادي والمسافرون الأضاحي.mp3","categories":["الهدي والأضاحي"]},{"id":3820,"question":"لو استدلَّ الموجبون للأضاحي بهذا؛ بكون الرسول ﷺ أمر لمن ذبح قبل الصلاة أن يُضحي بأخرى مكانها بعد الصلاة، قالوا: هذا يدل على الوجوب؟","title":"ماذا يجب على من ضحى قبل الصلاة؟","answer":"الجواب: الأدلة الأخرى دالة على أنه للسنية؛ لأنه ﷺ قال: مَن أراد أن يُضحي فلا يأخذ من شعره ...","link":"https://binbaz.org.sa/fatwas/24021/ماذا-يجب-على-من-ضحى-قبل-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من ضحى قبل الصلاة، يضحي بأخرى مكانها بعد الصلاة.mp3","categories":["الهدي والأضاحي"]},{"id":4224,"question":"إعطاء الكافر من الأضحية؟","title":"هل يجوز إعطاء الكافر من الأضحية؟","answer":"الجواب: ما في مانع، صدقة تطوع.","link":"https://binbaz.org.sa/fatwas/24491/هل-يجوز-اعطاء-الكافر-من-الاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إعطاء الكافر من الأضحية.mp3","categories":["الهدي والأضاحي"]},{"id":4659,"question":"بعث الهدي في غير أشهر الحج؟","title":"هل يجوز بعث الهدي في غير أشهر الحج؟","answer":"الجواب: لا بأس، يبعث الهدي ولا عليه شيء، النبي بعث الهدي مرات وبقي عند أهله حلالًا.\nس: في غير أشهر الحج؟\nج: في غير أشهر الحج.\nس: في مثل هذه الأيام؟\nج: إذا بعثه يُنحر في مكة ويُقسم على الفقراء، الحمد لله.","link":"https://binbaz.org.sa/fatwas/24950/هل-يجوز-بعث-الهدي-في-غير-اشهر-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بعث الهدي في غير أشهر الحج.mp3","categories":["الهدي والأضاحي"]},{"id":4729,"question":"له الانتفاع بها قبل كذلك؛ من شرب اللبن وحمل المتاع؟","title":"حكم الاتنفاع بالهدي وشرب لبنه وركوبه","answer":"نعم إذا احتاج إلى ذلك، اللبن يشربه، لا يضيعه، وحمل المتاع إذا احتاج إلى ذلك ولا يشقّ عليها، لا حرج، مثلما يركبها.\nس: ركوب الهدي يُعتبر سنةً؟\nج: إذا دعت الحاجةُ، أما إذا كان معه ما يسدّه فالحمد لله، لا يركب، إذا أُلجئتَ إليها.\nس: مباح يعني؟\nج: نعم مباح، من باب المباح.","link":"https://binbaz.org.sa/fatwas/25038/حكم-الاتنفاع-بالهدي-وشرب-لبنه-وركوبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الاتنفاع بالهدي وشرب لبنه وركوبه.mp3","categories":["الهدي والأضاحي"]},{"id":4732,"question":"إذا كان ذبح هدي التَّمتع، في منًى زحمة، وخرج إلى مُزدلفة وذبح؟","title":"هل يجوز ذبح هدي التَّمتع في مُزدلفة؟","answer":"الحرم كله ذبح، منى أفضل، وإن ذبح في مكة أو في مزدلفة ما في بأس، الأمر واسع والحمد لله، إذا دخل مكة وذبح داخل مكة الحمد لله، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/25042/هل-يجوز-ذبح-هدي-التمتع-في-مزدلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ذبح هدي التَّمتع في مُزدلفة.mp3","categories":["الهدي والأضاحي"]},{"id":4733,"question":"بالنسبة للشركات التي تأخذ الهدي وينقلونه إلى خارج المملكة؟","title":"ما حكم نقل الهَدْي خارج مكة؟","answer":"يُجزئ، لكن كونه يذبح الضَّحايا في بلده ليُطعم جيرانه وأهله أفضل وأولى، أما الهدية التي هي واجبة عن محظورٍ أو ترك واجبٍ فهي تُذبح في مكة للفقراء من الحجاج، أما الضَّحايا وهدايا التطوع وهدي التمتع والقران فهذا يأكل ويطعم، سواء في مكة أو في غير مكة.","link":"https://binbaz.org.sa/fatwas/25043/ما-حكم-نقل-الهدي-خارج-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم نقل الهدي خارج مكة.mp3","categories":["الهدي والأضاحي"]},{"id":4862,"question":"بالنسبة لشروط الأضحية، والعقيقة، والهدي، هل يكون مثل بعض سواء؟","title":"هل شروط الأضحية والعقيقة والهَدي سواء؟","answer":"نعم سواء، لا يُجزئ فيها إلا الذي في الأضاحي، لا في الهدي، ولا في العقيقة، لا يُجزئ فيها إلا ما يُجزئ في الأضاحي.","link":"https://binbaz.org.sa/fatwas/25333/هل-شروط-الاضحية-والعقيقة-والهدي-سواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شروط الأضحية، والعقيقة، والهدي هل هي سواء.mp3","categories":["الهدي والأضاحي","أحكام المولود"]},{"id":5077,"question":"متى يبدأ الصيام لمَن لم يستطع الهدي في التَّمتع؟","title":"متى يصوم مَن لم يستطع الهدي في التَّمتع؟","answer":"الجواب: من حين يحلّ من عمرته يبدأ بالصيام، ولو في ذي القعدة، ولو في شوال، يصوم ثلاثة أيام، أما السبعة فالأفضل أن يُؤجّلها إذا رجع إلى بلاده، فإن صامها في مكة فلا بأس؛ لأن الله يقول: فَصِيَامُ ثَلَاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ [البقرة:196]. والأفضل أن يصوم الثلاث قبل عرفة، حتى يكون في يوم عرفة مُفطرًا، هذا هو الأفضل، فإن لم يتيسر له ذلك بأنه يرجو أن يشتري ثم عجز صام أيام التَّشريق رخصةً خاصةً لمن عجز عن الهدي، يصوم أيام التشريق فقط دون غيره من الناس؛ لأنها أيام أكل وشرب، وأيام ذكر، وأيام نحر، فلا يجوز صومها لأحدٍ من الناس إلا لمن عجز عن الهدي ولم يتيسر له الصوم قبل عرفة.","link":"https://binbaz.org.sa/fatwas/29417/متى-يصوم-من-لم-يستطع-الهدي-في-التمتع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يصوم من لم يستطع الهدي في التمتع؟.mp3","categories":["الهدي والأضاحي"]},{"id":5214,"question":"يقول السائل فضيلة الشيخ: أريد أن أتمتع بالحج في العام القابل بإذن الله، ولكن إذا أردتُ أن أُضحي عني وعن أهلي فهل يُجزئ هدي الحج؟","title":"هل يُجزئ هدي الحج عن الأضحية؟","answer":"الجواب: الهدي غير الضَّحية، بارك الله فيك، فالهدي شيءٌ، والضَّحية شيءٌ، الهدي عن التَّمتع، والضَّحية مُستحبَّة للجميع وإن لم يحجّ، مُستحبَّة لجميع الناس، في الحضر والبدو، والقرى والأمصار، الضَّحية واحدةٌ عن الرجل وأهل بيته. كان الرسول ﷺ يُضحِّي بكبشين عنه وعن أهل بيته وعن أمة محمدٍ ﷺ، كل سنة يُضحِّي بكبشين أملحين أقرنين: أحدهما يذبحه عن نفسه وأهل بيته، والثاني عمَّن وحَّد الله من أمته عليه الصلاة والسلام. فالسنة لك يا عبدالله أن تُضحي بواحدةٍ عنك وعن أهل بيتك: زوجتك وعيالك ووالديك، وإن ضحّيتَ بثنتين أو ثلاث فلا بأس، لا تدعها إن كنتَ قادرًا، أما إن كنتَ عاجزًا: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لكن مع القُدرة هي سنة غير واجبةٍ، لكنها سنة.","link":"https://binbaz.org.sa/fatwas/30158/هل-يجزى-هدي-الحج-عن-الاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 190.mp3","categories":["الهدي والأضاحي"]},{"id":5988,"question":"وأخ يسأل فيقول: والدتي توفيت، ولم توص أحدًا بأن يحج عنها، هل يجوز لي أن أحج عن والدتي؟","title":"هل الحج عن الوالدة جائز؟","answer":"الجواب: نعم إذا كانت ما حجت تحج عنها الفريضة، وإذا كانت قد حجت فهو نافلة، وجزاك الله خيرًا، هذا من أهم البر، وقد سمعتم الحديث أن النبي ﷺ سأله رجل، فقال: هل بقي من بر والدي شيء أبرهما بعد وفاتهما، قال: نعم، الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدها، وإكرام صديقهما، وصلة الرحم التي لا توصل إلا بهما.  فالحج عنهما من أفضل الأعمال، وإنفاذ عهدهما الوصية التي يوصيان بها إذا أوصيان بشيء تنفذ إذا كانت الوصية ما تخالف الشرع، تنفذ الصلاة عليهما، الدعاء لهما، وصلاة الجنازة، والاستغفار لهما.","link":"https://binbaz.org.sa/fatwas/1357/هل-الحج-عن-الوالدة-جاىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_315.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":6168,"question":"هل الإحصار في حج النفل لا بدّ من قضائه؟","title":"حكم القضاء لمن أحصر في الحج أو العمرة","answer":"الجواب: لا، إذا أحصر ما عليه شيء يتحلل، ولا عليه شيء، النبي ﷺ ما أمر الذين أحصروا أن يقضوا، وإنما سميت عمرة القضاء؛ لأنها عمرة مصالحة، ولم يأمر النبي ﷺ الناس الذين حصروا معه أن يقضوا، بل سميت عمرة القضاء والقضية للمصالحة يعني، فلا يلزم إذا أحصر، ومنع من دخول مكة فإنه ينحر هديه، ثم يتحلل، وليس عليه قضاء؛ لأن النبي ﷺ نحر هديه، وحلق رأسه، ولم يأمر الناس بأن يقضوا هذه العمرة، بل اعتمر بعد ذلك بغير إلزام لأحد، من أراد أن يعتمر معه اعتمر، ومن لا فلا، ولم يلزم أحدًا.  فدل ذلك على أن العمرة التي يحصر عنها، أو الحج لا يلزم قضاؤها، ولكن إذا أحصر ولم يتمكن من دخول مكة، فإنه يتحلل ينحر هديه إن كان عنده هديه، أو يصوم عشرة أيام، ثم يحلق؛ لأن الله قال: فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ وَلَا تَحْلِقُوا رُءُوسَكُمْ حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ [البقرة:196] فلا يحلق إلا بعد الذبح، ولم يقل عليكم حجة أخرى، أو عمرة أخرى، بل سكت ﷺ.","link":"https://binbaz.org.sa/fatwas/1622/حكم-القضاء-لمن-احصر-في-الحج-او-العمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_513.mp3","categories":["الإحصار","الهدي والأضاحي"]},{"id":6215,"question":"أحد يسأل ما حكم البتراء، والجماء من الأضحية، والهدي؟","title":"حكم الأضحية بالبتراء والجماء","answer":"الجواب: لا حرج، الجماء والبتراء لا حرج، التي ذنبها صغير، أو جماء ما لها قرون، ما فيها شيء، لكن المقطوعة لا، إذا قطع قرنها، أو قطعت إليتها؛ ما تجزئ، لكن إذا كان من خلقة جماء، ما لها قرون بالخلقة، أو صمعاء ما لها أذن، أو بتراء ذنبها صغير؛ فهذا ما فيه بأس، أما كونها تقطع إليتها، أو يزال قرنها، أو يكسر، أو تقطع الأذن لا.","link":"https://binbaz.org.sa/fatwas/1713/حكم-الاضحية-بالبتراء-والجماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_567.mp3","categories":["الهدي والأضاحي"]},{"id":6259,"question":"رجل حج هذا العام متمتعًا، ثم فقد ماله في أيام الحج، فلم يستطع ذبح الهدي، ولم يصم في مكة، ثم رجع إلى الرياض، وهو يسأل الآن ماذا عليه؟","title":"حكم من حج فلم يستطع ذبح الهدي لفقد المال","answer":"الجواب:  عليه أن يصوم عشرة أيام في الرياض ويكفي عن الهدي، إلا إذا أحب أن يهدي الآن، إذا كان يستطيع أن يرسل هديه إلى مكة، ويذبح هناك؛ كفى عن الصيام، وإن صام؛ فلا بأس؛ لأن العبرة بحاله وقت وجوبه، فإذا كان ذاك الوقت عاجزًا، وقد فقد ماله؛ فالصيام يجزئه إلا إذا صام هنا أجزأته.  وكما ينبغي أن يفرق الصيام، ينبغي أن يصوم ثلاثة أيام في الحج، أقل شيء في الأيام الثلاثة الأخيرة، أيام التشريق، هذا هو الواجب عليه مع القدرة، أما إذا كان عاجزًا، واستطاع الصيام؛ يصوم الثلاث مع السبع، يكون عشر يصومهن، وإذا تيسر له الهدي، وأحب أن يرسله إلى مكة، ولا يصوم؛ أرسله إلى مكة مع ثقة، أو سافر به هو، وذبحه هناك بنية الهدي، فأكل، وأطعم.","link":"https://binbaz.org.sa/fatwas/1777/حكم-من-حج-فلم-يستطع-ذبح-الهدي-لفقد-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_616.mp3","categories":["الهدي والأضاحي"]},{"id":6268,"question":"رجل حج هذا العام متمتعًا، ثم فقد ماله في أيام الحج، فلم يستطع ذبح الهدي، ولم يصم في مكة، ثم رجع إلى الرياض، وهو يسأل الآن ماذا عليه؟","title":"حكم من حج فلم يستطع ذبح الهدي لفقد المال","answer":"الجواب:  عليه أن يصوم عشرة أيام في الرياض ويكفي عن الهدي، إلا إذا أحب أن يهدي الآن، إذا كان يستطيع أن يرسل هديه إلى مكة، ويذبح هناك؛ كفى عن الصيام، وإن صام؛ فلا بأس؛ لأن العبرة بحاله وقت وجوبه، فإذا كان ذاك الوقت عاجزًا، وقد فقد ماله؛ فالصيام يجزئه إلا إذا صام هنا أجزأته.  وكما ينبغي أن يفرق الصيام، ينبغي أن يصوم ثلاثة أيام في الحج، أقل شيء في الأيام الثلاثة الأخيرة، أيام التشريق، هذا هو الواجب عليه مع القدرة، أما إذا كان عاجزًا، واستطاع الصيام؛ يصوم الثلاث مع السبع، يكون عشر يصومهن، وإذا تيسر له الهدي، وأحب أن يرسله إلى مكة، ولا يصوم؛ أرسله إلى مكة مع ثقة، أو سافر به هو، وذبحه هناك بنية الهدي، فأكل، وأطعم.","link":"https://binbaz.org.sa/fatwas/1777/حكم-من-حج-فلم-يستطع-ذبح-الهدي-لفقد-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_616.mp3","categories":["الهدي والأضاحي"]},{"id":6477,"question":"هل يجوز الصيام، أو الصدقة بدلًا من الدم على سبيل التخيير، أم الأولوية للدم؟","title":"أحكام الهدي","answer":"الجواب: لا، هدي التمتع، والقران لا بد من الدم، لا تجزئ فيه الصدقة، ولا المال، أما غيره مثل فدية الأذى الذي غطى رأسه عامدًا، أو تطيب عامدًا، هذا يخير بين: صيام ثلاثة أيام، أو ذبح شاة، أو إطعام ستة مساكين، يخير إذا غطى رأسه، أو لبس المخيط عامدًا ذاكرًا، أو تطيب أو قلم أظفاره، أو حلق شعره، فهذه الأمور الخمسة فيها أحد ثلاثة أشياء: إما صيام ثلاثة أيام في أي مكان، وإما إطعام ستة مساكين، لكل مسكين نصف صاع، وإما ذبح شاة في الحرم في مكة.","link":"https://binbaz.org.sa/fatwas/2231/احكام-الهدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_851.mp3","categories":["الهدي والأضاحي"]},{"id":6492,"question":"هل يجوز الصيام، أو الصدقة بدلًا من الدم على سبيل التخيير، أم الأولوية للدم؟","title":"أحكام الهدي","answer":"الجواب: لا، هدي التمتع، والقران لا بد من الدم، لا تجزئ فيه الصدقة، ولا المال، أما غيره مثل فدية الأذى الذي غطى رأسه عامدًا، أو تطيب عامدًا، هذا يخير بين: صيام ثلاثة أيام، أو ذبح شاة، أو إطعام ستة مساكين، يخير إذا غطى رأسه، أو لبس المخيط عامدًا ذاكرًا، أو تطيب أو قلم أظفاره، أو حلق شعره، فهذه الأمور الخمسة فيها أحد ثلاثة أشياء: إما صيام ثلاثة أيام في أي مكان، وإما إطعام ستة مساكين، لكل مسكين نصف صاع، وإما ذبح شاة في الحرم في مكة.","link":"https://binbaz.org.sa/fatwas/2231/احكام-الهدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_851.mp3","categories":["الهدي والأضاحي"]},{"id":6981,"question":"رجل سوداني الجنسية، جاء إلى المملكة لكي يأخذ العمرة، وجلس فيها على طريقة غير قانونية لمدة شهرين بدون إقامة، وبعد ذلك أراد أن يذهب إلى الحج، وفي يوم سبعة ذي الحجة أحرم في أبيار علي، وأراد الحج، وبعد ذلك وقع في أيدي السلطة، وسفروه إلى بلاده السودان -وهو قد أحرم ونوى الحج- فهل يلزمه في ذلك شيء مما حصل له من هذه الأشياء الموضحة في هذه الرسالة، أفيدونا جزاكم الله خيرًا في الدنيا والآخرة، حيث إني في حيرة من أمري؟","title":"الواجب على من أحرم ونوى الحج ثم أحصر","answer":"الجواب:\n\nحكمه حكم المحصر، إذا منع من الدخول؛ حكمه حكم المحصر، عليه أن يهدي -يذبح ذبيحة- ويحلق ويحل، هذا محصر، يقول الله سبحانه: فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196] معناه: أنه إذا منع، وقد أحرم؛ يذبح شاة، أو سبع بدنة، أو سبع بقرة إن قدر، وإن عجز؛ يصوم عشرة أيام، ويحلق رأسه، ويحل هذا هو. \n\nالسؤال: ...؟\nالجواب: في محله الذي أحصر فيه.\n\nالسؤال:...؟\n\nالجواب: لا.\n\nالسؤال: ...؟\n\nالجواب: في أي مكان، ما هو بلزوم مكانه، ولو في بلاده.","link":"https://binbaz.org.sa/fatwas/2906/الواجب-على-من-احرم-ونوى-الحج-ثم-احصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1354.mp3","categories":["الإحصار","الهدي والأضاحي"]},{"id":7116,"question":"نشكر الله  ثم نشكركم على هذه الندوة المباركة، جعلها الله في ميزان حسناتكم يوم القيامة، سماحة والدنا العزيز، حضرت أسرتي من مصر لأداء فريضة الحج -وهم مع مطوف- ومعهم حجاج كثيرون جدًا، وذهبت لأكون برفقتهم قبل الحج، فوجدت المسؤول عنهم قد قال لهم: لا بد من عمل، أو من ذبح الهدي قبل يوم العيد، وجمع منهم فلوسًا، وفعل لهم ذلك، وعندما قلت له: هذا خطأ، قال: نحن نفعل ذلك منذ سنوات؛ بناء على فتوى برأي الإمام الشافعي في مصر مع مطوفنا، وذبح لهم يوم سبعة ذي الحجة، ومجموعة أخرى بعدها قبل العيد، وقلت: إن الله  قال: بسم الله الرحمن الرحيم: فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:2] وأخذ أن من أركان الحج: الذبح ابتداء من يوم العيد، إلى آخر أيام التشريق على حد علمي، ما الصحيح، وإن أخطأ فما العلاج، مع العلم جهل كل الحجاج الموجودين بذلك، وقد وكلوا المسؤول عنهم بناء على فتواه لهم؟","title":"حكم من ذبح الهدي قبل يوم العيد في الحج","answer":"الجواب:\n\nالذبح ليس من أركان الحج، أركان الحج: الإحرام، والوقوف بعرفة، والطواف، والسعي، هذه أركانه، والذبح ليس من أركان الحج، وإنما هو واجب في حق بعض الحجاج لا كل الحجاج، في حق من تمتع بالعمرة إلى الحج، وهو الذي أحرم بالعمرة في أشهر الحج، ثم أحرم بالحج بعدها في عامه، أو أحرم بهما جميعًا، بالحج والعمرة جميعًا، هذا هو الذي عليه الهدي.\n\nوالواجب أن يذبح في أيام النحر: يوم العيد، والحادي عشر، والثاني عشر، والثالث عشر، هذه أيام الذبح، أربعة أيام على الصحيح، الواجب أن يكون الذبح فيها، والنبي ﷺ وأصحابه ذبحوا فيها، وكان معهم هدي قد قدموا به من المدينة، ولم يذبحوه إلا في يوم النحر، والنبي ﷺ بقي على إحرامه حتى ذبح يوم النحر، ولو كان يجوز قبل يوم النحر لذبحوا، وأكلوا، وأطعموا الناس؛ لأنهم في حاجة إلى ذلك، فلما أخرها ﷺ إلى يوم النحر؛ دل ذلك على أنه لا ذبح إلا في أيام النحر، وهذا هو الذي عليه جمهور أهل العلم.\n\nنعم للشافعي فتوى في هذا، ذهب جماعة من الشافعية إلى جوازه قبل العيد، وبعضهم أجازه بعد الإحرام بالحج، لا قبل الإحرام، ولكن الصواب أنه لا ينحر الهدي إلا في أيام العيد كما قاله الجمهور، وكما دلت عليه السنة. \n\nوالذين نحروا قبل يوم العيد في اليوم السابع، أو قبله، أو في اليوم الثامن، أو التاسع عليهم أن ينحروا بعد ذلك، وعليهم أن يقضوا ذلك ولو بعد أيام العيد، ولو هذه الأيام، عليهم أن يقضوا ذلك الهدي إذا كانوا متمتعين، أو قارنين بين الحج والعمرة، عليهم أن يوكلوا إذا كانوا سافروا، أن يوكلوا من يذبح عنهم في مكة من الثقات عن كل من نحر قبل العيد.\n\nالسؤال: وإذا كان النحر لمجرد أضحية، أو تطوع؟\n\nالجواب: إذا كانت أضحية، أو تطوعًا ما عليه شيء، ليس عليه إعادة.","link":"https://binbaz.org.sa/fatwas/3145/حكم-من-ذبح-الهدي-قبل-يوم-العيد-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1503.mp3","categories":["الهدي والأضاحي"]},{"id":7846,"question":"سؤاله الثاني - سؤال شريف سعدون الشريف من العراق- يقول: طلب منا بعض الرفاق نحر هدينا فور وصول مكة فذبحنا في خمسة وعشرين ذي القعدة، والآن ذهبت أيام التشريق وقد رأينا جميع الناس يذبحون في يوم العيد فما بعده، فهل عملنا صحيح؟ وما الذي يجب علينا وفقكم الله؟ علماً أننا الآن عازمون على الذهاب عن السعودية، جزاكم الله عنا خيراً؟","title":"حكم محرم ذبح الهدي قبل يوم النحر","answer":"الجواب: الواجب على من عليه هدي لكونه حج قارناً أو متمتعاً بالعمرة إلى الحج أنه يذبح أيام الذبح، وهي الأيام التي ذبح فيها النبي وأصحابه عليه الصلاة والسلام، يوم العيد وأيام التشريق الثلاثة أربعة أيام، هذه أيام الذبح، والنبي ﷺ قدم ومعه هدي إبل فلم يذبحها حتى جاء يوم العيد، وهكذا أصحابه، فالذي ذبح قبل العيد عليه أن يعيد، إذا ذبح هديه قبل أن يتعيد قبل يوم العيد عليه أن يعيد ذلك، يشتري في مكة هدي ويذبح في مكة بعد الحج متى تيسر له ذلك، يذبح في مكة في الحرم ويقسمه بين فقراء مكة بين الفقراء في الحرم، بدلاً من ذاك الهدي الذي ذبحه قبل وقته، فإن كان عاجزاً ليس عنده قدرة فإنه يصوم عشرة أيام بدلاً من ذلك الهدي، هذا هو المشروع ونسأل الله للجميع التوفيق. نعم.\nالمقدم: شكراً لسماحة الشيخ عبد العزيز .","link":"https://binbaz.org.sa/fatwas/5238/حكم-محرم-ذبح-الهدي-قبل-يوم-النحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_053/05305.mp3","categories":["الهدي والأضاحي"]},{"id":7863,"question":"سؤاله الأخير والأخير في هذا اللقاء، يقول: هل يجوز ذبح الفدى في عيد رمضان بدلاً من عيد الأضحى؛ لأتمكن من التوزيع على الفقراء الذين أعرفهم في بلدي ولتواجدي دائماً بعيداً عنهم في عيد الأضحى من كل عام؟","title":"حكم ذبح الأضحية في عيد رمضان","answer":"الجواب: إذا كان المقصود الضحية المشروعة في عيد الأضحى، أو الفدي الذي يلزم المتمتع أو القارن في الحج والعمرة هذا لا، لا يذبح إلا في مكة في أيام الذبح، وهي يوم العيد وأيام التشريق، تذبح الهدي هدي التمتع وهكذا الضحايا كلها تذبح في أيام العيد -عيد النحر- يوم العيد وثلاثة أيام بعده، ولا تذبح في عيد الفطر ولا في شهر ذي الحجة بعد العيد ولا قبله ولا في شهر ذي القعدة،، إنما تذبح في أيام العيد أيام عيد النحر، وهي أربعة أيام يوم النحر وهو اليوم العاشر من ذي الحجة وثلاثة أيام بعده، تذبح فيها الضحايا والهدايا الشرعية التي تجب على المتمتع والقارن أو الذي يتطوع بها المطوعون تذبح في هذه الأيام.\nأما إذا كان القصد أن يتطوع بشيء ليقسمها على القرابة فلا بأس، تكون هذه صدقة، إذا أراد يذبح ناقة أو بقرة أو شاة في بلاده يوزعها بين أقاربه صدقة أو صلة هذا طيب، لكن ما تسمى هذه هدياً ولا ضحية ولا فدية، الفدية ما يجب على الإنسان في التمتع والقران هذا يذبح أيام النحر، أما إذا كان فدية عن تركه واجباً أو عن فعله محرماً فهذه تذبح في الحرم عما ترك من الواجب أو عما فعل من المحرم في نفس الحرم وتوزع بين فقراء الحرم. نعم.\nالمقدم: أحسنتم أثابكم الله.\nشكراً سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/5327/حكم-ذبح-الاضحية-في-عيد-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_056/05614.mp3","categories":["الهدي والأضاحي"]},{"id":7864,"question":"سؤاله الأخير والأخير في هذا اللقاء، يقول: هل يجوز ذبح الفدى في عيد رمضان بدلاً من عيد الأضحى؛ لأتمكن من التوزيع على الفقراء الذين أعرفهم في بلدي ولتواجدي دائماً بعيداً عنهم في عيد الأضحى من كل عام؟","title":"حكم ذبح الأضحية في عيد رمضان","answer":"الجواب: إذا كان المقصود الضحية المشروعة في عيد الأضحى، أو الفدي الذي يلزم المتمتع أو القارن في الحج والعمرة هذا لا، لا يذبح إلا في مكة في أيام الذبح، وهي يوم العيد وأيام التشريق، تذبح الهدي هدي التمتع وهكذا الضحايا كلها تذبح في أيام العيد -عيد النحر- يوم العيد وثلاثة أيام بعده، ولا تذبح في عيد الفطر ولا في شهر ذي الحجة بعد العيد ولا قبله ولا في شهر ذي القعدة،، إنما تذبح في أيام العيد أيام عيد النحر، وهي أربعة أيام يوم النحر وهو اليوم العاشر من ذي الحجة وثلاثة أيام بعده، تذبح فيها الضحايا والهدايا الشرعية التي تجب على المتمتع والقارن أو الذي يتطوع بها المطوعون تذبح في هذه الأيام.\nأما إذا كان القصد أن يتطوع بشيء ليقسمها على القرابة فلا بأس، تكون هذه صدقة، إذا أراد يذبح ناقة أو بقرة أو شاة في بلاده يوزعها بين أقاربه صدقة أو صلة هذا طيب، لكن ما تسمى هذه هدياً ولا ضحية ولا فدية، الفدية ما يجب على الإنسان في التمتع والقران هذا يذبح أيام النحر، أما إذا كان فدية عن تركه واجباً أو عن فعله محرماً فهذه تذبح في الحرم عما ترك من الواجب أو عما فعل من المحرم في نفس الحرم وتوزع بين فقراء الحرم. نعم.\nالمقدم: أحسنتم أثابكم الله.\nشكراً سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/5327/حكم-ذبح-الاضحية-في-عيد-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_056/05614.mp3","categories":["الهدي والأضاحي"]},{"id":7932,"question":"سماحة الشيخ! نبدأ أولاً برسالة المستمع (أ. ح. م. د) زهراني من القنفذة، ملخص رسالته هذه يقول: هل تجزئ الأضحية التي في بطنها حمل، علماً: أن الذي ذبحها لا يعلم، وقد خطب إمام صلاة العيد وذكر بأنها لا تجزئ؟","title":"حكم الأضحية الحبلى","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nالذبيحة التي فيها ولد تجزي بلا شك، والخطيب الذي قال: إنها لا تجزي. مخطئ وغلطان، البقرة والناقة والشاة من الغنم من الضأن والمعز إذا كان في بطنها ولد تجزي بلا شك، والذي قد خطب بأنها لا تجزي قد غلط وقال قولاً لا حجة له فيه، ولا أعلم به قائلاً من أهل العلم، بل ذلك خطأ محض. نعم.","link":"https://binbaz.org.sa/fatwas/5445/حكم-الاضحية-الحبلى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_066/06601.mp3","categories":["الهدي والأضاحي"]},{"id":8039,"question":"فضيلة الشيخ عبد العزيز هذه رسالة وردتنا من أحد السادة يقول فيها: أرجو عرض رسالتي هذه على الشيخ عبد العزيز بن عبد الله بن باز، وهو من المملكة العربية السعودية من الأحساء الهفوف ورداي محمد محمد وهو من جمهورية مصر العربية، لكنه يعمل هنا يقول: أديت الحج في عام (1397هـ)، وعندما لبست الإحرام نويت الحج والعمرة معاً، ولم أذبح ثم صمت عشرة أيام بعد أيام الحج، فما حكم عملي هذا؟","title":"حكم من حج متمتعاً وصام ولم يذبح الهدي","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا شك أن من أحرم بحج وعمرة يعتبر متمتعاً، وعليه دم التمتع، فالسائل عليه دم التمتع، فإذا كان عاجزاً فالصوم الذي فعله مجزئ، أما إذا كنت أيها السائل تستطيع الدم، فإن عليك أن تذبح ذبيحة تجزئ في الأضحية، يعني: رأس من الغنم أو سبع بدنة أو سبع بقرة في مكة المكرمة؛ لأن هذا هو الواجب في التمتع والقران، وعملك يسمى: قراناً، ويسمى: تمتعاً، فعليك الهدي، فإذا كنت عاجزاً لا تستطيع ذلك الوقت، وصمت العشرة الأيام أجزأت العشرة والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/5665/حكم-من-حج-متمتعا-وصام-ولم-يذبح-الهدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08101.mp3","categories":["الهدي والأضاحي"]},{"id":8042,"question":"سؤاله الثاني يقول: في العام الثاني ذهبت إلى الحج ونويت الحج لوالدي المتوفى حج مفرد ولم أذبح هل علي شيء أم لا؟","title":"حكم الذبح لمن حج مفردًا","answer":"الجواب: أما الذي يحرم بالحج المفرد فليس عليه شيء.. ليس عليه هدي ولا صيام. نعم.","link":"https://binbaz.org.sa/fatwas/5836/حكم-الذبح-لمن-حج-مفردا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08102.mp3","categories":["الهدي والأضاحي"]},{"id":8149,"question":"سؤالها الثاني تقول: هل حدد الإسلام عدد الأضاحي التي يضحي بها المسلم يوم عيد الأضحى، وكم عددها إن وجد عدد؟","title":"عدم تحديد الشريعة لعدد الأضاحي","answer":"الجواب: ما فيها تحديد، النبي ﷺ كان يضحي بثنتين عليه الصلاة والسلام إحداهما عنه وعن أهل بيته، والثانية عما وحد الله من أمة محمد عليه الصلاة والسلام، فإذا ضحى الإنسان بواحدة أو بثنتين أو بأكثر فلا بأس، قال أبو أيوب الأنصاري : كنا نضحي في عهد النبي ﷺبالشاة الواحدة فنأكل ونطعم، ثم تباهى الناس بعد ذلك.\nفالحاصل أن الواحدة تكفي، إذا ضحى الإنسان في بيته بواحدة عنه وعن أهل بيته حصلت السنة بهذا، وإن ضحى بأكثر ثنتين ثلاث أربع أو بناقة أو بقرة فلا بأس، يأكل ويطعم ويتصدق، كل هذا طيب إذا كان اللحم يؤكل، أما أنه يذبح في العيد ويطرح للأسواق لا هذا ما يجوز، هذا إضاعة مال، لكن إذا كان يذبح شيء يؤكل ويقسم على الفقراء أو الأقارب هذا طيب قل أو كثر، ولكن أقل شيء واحدة.. أقل شيء واحدة، تذبح عن الرجل وأهل بيته ولو كانوا كثيرين، عنه وعن زوجته وعن أولاده وعن والديه وعن شبه ذلك ممن هو معه في البيت. نعم.","link":"https://binbaz.org.sa/fatwas/5956/عدم-تحديد-الشريعة-لعدد-الاضاحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_090/09008.mp3","categories":["الهدي والأضاحي"]},{"id":8198,"question":"هذه رسالة وردتنا أيضاً حول الذبح، من نورة الدوسري ، تقول أختكم في الإسلام: هل الذي يذبحه الحاج في مكة يوم النحر، يجزيه عن الضحية التي يقوم المسلمون بذبحها يوم العيد، بقصد أنها أضحية، أم أن من أراد الحج؟ فهل يجب عليه أن يضحي في بلده، ومن ثم يحج في عام آخر؟","title":"الفرق بين الأضحية والهدي","answer":"الجواب: الضحية شيء والهدي شيء، فإذا أهدى هدي التمتع، هذا يذبح في منى أو في مكة أيام النحر؛ لأن الرجل أو المرأة إذا أحرم بالعمرة في أشهر الحج ثم حج أو حج بقران، بهما جميعاً هذا عليه هدي، يعني عليه ذبيحة من الغنم أو سبع من البدنة أو سبع من البقرة؛ لأن الله سبحانه قال: فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196] وما استيسر إما شاة من ثني المعز أو من جذع الضأن، أو سبع بدنة، أو سبع بقرة، يجب عليه ذلك، فإن عجز صام عشرة أيام ثلاثة أيام في الحج قبل يوم عرفة أفضل، وسبعة إذا رجع إلى أهله، فهذه غير مسألة الضحية، أما الضحية هذه يذبحها الناس في بلدانهم، وقراهم وفي البوادي، سنة أيام عيد النحر، فيضحي الإنسان بشاة عنه وعن أهل بيته، أو يضحي بسبع بدنة أو بسبع بقرة، هذه سنة عن الرجل وأهل بيته، عنه وعن زوجته وأولاده سنة، ولو كان حاجاً، إذا وكل أهل بيته يذبحونها عنه، أو ذبحها في منى أو في مكة مع الهدي، كل هذا لا بأس به، فالهدي شيء واجب، والضحية سنة ما هي بواجبة، ما هي بلازمة الضحية هي سنة مؤكدة مع القدرة، وليست واجبة.\nفالذي يحج إذا تركها لا حرج عليه إذا اكتفى بالهدي هدي التمتع لا بأس، وإن ضحى مع ذلك في بلاده، وكل عليها أهل بيته أو غيرهم فلا بأس، وإن ضحى في منى، أو في مكة فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/6012/الفرق-بين-الاضحية-والهدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_094/09406.mp3","categories":["الهدي والأضاحي"]},{"id":8200,"question":"أيضاً لديها سؤال آخر تقول: ما حكم من حج ولم يضح لنفسه خاصة، ولكنه ذبح الهدي في مكة يوم النحر، أو أيام التشريق، بالأصح؟","title":"حكم من حج ولم يضح عن نفسه","answer":"الجواب: تقدم فيها الجواب عن هذا وأنه لا حرج في ذلك، الضحية ما هي بلازمة، إذا حج وأفدى بالهدي المعروف ولم يضح فلا بأس.","link":"https://binbaz.org.sa/fatwas/6013/حكم-من-حج-ولم-يضح-عن-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_094/09407.mp3","categories":["الهدي والأضاحي"]},{"id":8202,"question":"أيضاً تقول: هل من أراد أن يضحي خاصة النساء، وذلك لأنه عندنا بعض أمهاتنا وأجدادنا الأوائل، يقولون لنا: لا تقربوا الحناء إلا بعد ذبح الضحية، فهل هو صحيح أم أنها خرافات؟","title":"حكم استعمال الحناء لمن أرادت الأضحية","answer":"الجواب: هذا لا أصل له، من أراد أن يضحي لا بأس أنها تتحنى، لا بأس أنها تتطيب، لا بأس أنها تتروش متى شاءت، ما هو بحرام، لكن لا تأخذ شعر ولا ظفر، إذا دخل شهر ذو الحجة، جاء عن النبي ﷺ أنه قال: من أراد أن يضحي ودخل شهر ذو الحجة، فلا يأخذ من شعره ولا من أظفاره شيئًا، وفي لفظ: ولا من بشرته شيئًا، فالذي يضحي عنه وعن أهل بيته، أو عنه وحده، أو عن أبيه أو عن أمه، يعني تبرعًا منه، هذا إذا دخل الشهر شهر ذي الحجة، فإنه لا يأخذ من شعره ولا من أظفاره ولا من بشرته شيئاً لا يقص شعراً ولا ظفراً، ولا يقطع جلدة من جلدته أو من بدنه حتى يضحي، إما في يوم النحر أو بعده، هذا هو المشروع، لكن لا بأس أن تنقض شعرها، ....... كغسله، لا بأس أن تحنى لا بأس، لكن لا تكده بالمشط حتى يتقطع الشعر حتى تضحي، ولكن غسله وفركه ونقضه كل هذا لا بأس به، إنما الممنوع قطعه بشد أو بغيره.","link":"https://binbaz.org.sa/fatwas/6014/حكم-استعمال-الحناء-لمن-ارادت-الاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_094/09408.mp3","categories":["الهدي والأضاحي"]},{"id":8203,"question":"هذه رسالة وردتنا من النماص من سعد الشهري ، يقول في رسالته: نحن في منطقة الجنوب بعضنا يضحي ببقر، أي: كل سبعة أشخاص يشترون بقرة ويضحون بها، أي كل واحد منهم يأخذ سبع هذه البقرة، عنه وعن أهل بيته منذ قديم الزمان، وفي هذا العام قال بعض القضاة: إن البقرة لا يجوز أن يضحي بها؛ لأنها لا تضحي إلا عن سبعة أشخاص، دون عوائلهم، فأرجو إرشادنا في هذا الأمر، هل السبع من البقرة يضحي عن الرجل وأهل بيته، أم وحده دون أهله؟ ولكم منا جزيل الشكر؟","title":"إجزاء سبع البقرة عن المضحي وأهله","answer":"الجواب: قد صح عن النبي عليه الصلاة والسلام أن أمر بالاشتراك في البدنة والبقرة عن سبعة، فإذا أجزأت عن سبعة من الناس، في الضحايا والهدايا، فهكذا يجوز للرجل أن يجعل السبع الذي يذبحه عن نفسه، يكون عنه وعن أهل بيته؛ لأن الرجل وأهل بيته كالشيء الواحد، فلا أرى بأساً في ذلك، حتى يكون السبع عنه وعن أهل بيته، ولا حرج في ذلك.\nبعض إخواننا من أهل العلم قد توقف في ذلك، وظن أن هذا فيه تشريك لأكثر من واحد، وهذا ليس بجيد؛ لأن الرجل وأهل بيته شيء واحد؛ ولهذا ذبح النبي ﷺ الشاة عنه وعن أهل بيته، والبدنة عن سبع شياه، والبقرة عن سبع شياه، فكل جزء منها من السبعة يقوم مقام الشاة، والشاة تذبح عن الرجل وعن أهل بيته، فهكذا سبعها، سبع بدنة، سبع بقرة، يضحي به الرجل عنه وعن أهل بيته، ولا حرج في ذلك إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/6010/اجزاء-سبع-البقرة-عن-المضحي-واهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_094/09404.mp3","categories":["الهدي والأضاحي"]},{"id":8736,"question":"رسالة مطولة بعض الشيء وصلت إلى البرنامج من إحدى الأخوات وتقول الأخت ( حياة ع ) أختنا سأقرأ رسالتها كما وردت سماحة الشيخ:السلام عليكم ورحمة الله وبركاته، إن بعض الناس يقولون: إن ذبح خروف - كبش- يوم عيد الأضحى المبارك -عرفة- إن الذبيحة تعتبر فريضة، والدليل على ذلك: أن النبي عليه الصلاة والسلام عندما جاء العيد ولم يكن لديه ذبيحة أراد ذبح ابنه، فأنزل الله  له كبشًا ليعيد به،  هل هذا صحيح؟ وهل يجب أن يكون مربى سنة كاملة ويسمن ليكون مسمى أو مسنى - كما هو تعبيرها- للعيد، ويفرق منه على سبعة بيوت، هل هذا صحيح؟ وهل هناك دليل على ذلك ورد عن الرسول ﷺ أو من تبعه من الصحابة؟ جزاكم الله خيرًا.","title":"بعض الأحكام المتعلقة بالأضحية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذه الذبيحة التي أشارت السائلة إليها غير صحيحة بهذا المعنى التي ذكرت، وإنما أصل ذلك: أن إبراهيم الخليل عليه الصلاة والسلام امتحنه الله فأمره بذبح ابنه بكره إسماعيل عليه الصلاة والسلام ليخلص قلبه لمحبته سبحانه دون محبة غيره جل وعلا، وكان إبراهيم هو خليل الله عليه الصلاة والسلام، وهو أفضل الناس في زمانه، وهو أفضل الخلق بعد محمد عليه الصلاة والسلام، فلما أراد ذبحه وتله للجبين ولم يبق إلا أن يوهي بالسكين إلى حلقه رحمه الله ورحم ابنه ورفع عنهما هذا الأمر وفداه بذبح عظيم وَنَادَيْنَاهُ أَنْ يَا إِبْرَاهِيمُ ۝ قَدْ صَدَّقْتَ الرُّؤْيَا إِنَّا كَذَلِكَ نَجْزِي الْمُحْسِنِينَ ۝ إِنَّهُ مِنْ عِبَادِنَا الْمُؤْمِنِينَ [الصافات:109-111]، فنسخ الله هذا الأمر وحصل المقصود بصفاء القلب وكمال المحبة لله ؛ لأنه قد طابت نفسه بذبح ابنه تقربًا إلى الله عز وجل وإكمالًا لمحبته له ، فلما تم المقصود وحصل المطلوب؛ نسخ الله هذا الأمر، وفدى الذبيح بذبح عظيم، وهو كبش عظيم، أرسله الله إليه ويقال: إنه جاء من الجنة، وأنه أهبط من الجنة فذبحه إبراهيم وفدى به ابنه إسماعيل ، وبقيت هذه سنة في المسلمين من ذاك الوقت وهو الضحايا في أيام عيد النحر.\nوكان النبي محمد عليه الصلاة والسلام يذبح في عيد النحر كبشين أملحين أقرنين، أحدهما: عن محمد وآل محمد أهل بيته، والثاني: عمن وحد الله من أمته عليه الصلاة والسلام.\nوصارت الضحية سنة في الأمة من عهد إبراهيم إلى عهد محمد نبينا عليه الصلاة والسلام إلى يومنا هذا، يستحب للمؤمن أن يضحي إذا كان عنده قدرة يوم النحر، شاة واحدة عنه وعن أهل بيته، فيأكلون ويطعمون وإن ضحى بأكثر فلا بأس.\nوليس هناك حاجة إلى أن يربيه في البيت ويسمنه، يشتريه من السوق أو يكون عنده في مزرعته لا بأس، لكن ليس من السنة أن يربيه، متى اشتراه من السوق كفى والحمد لله، ثم ليس من السنة أن يقسمه على سبعة أبيات لا، يأكل ويطعم كما قال الله تعالى: فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ الْفَقِيرَ [الحج:28] فيأكل منها ما تيسر ويطعم جيرانه وأقاربه والفقراء ما تيسر، وإن قسمها أثلاثًا فأكل ثلثًا وقسم بين أقاربه وجيرانه ثلثًا وأعطى للفقراء ثلثًا فكل ذلك حسن.\nوالمقصود من هذا: أنه يأكل ويطعم، وأنه يشتريه من السوق أو يربيه في البيت كل ذلك لا بأس به، وليس من شرط ذلك أن يقسمه بين سبعة أبيات هذا لا أصل له، بل يعطي من يشاء بيتين أو ثلاثة أو أقل أو أكثر من الفقراء أو من أقاربه ومن جيرانه الأمر في هذا واسع والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/6890/بعض-الاحكام-المتعلقة-بالاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_162/16201.mp3","categories":["الهدي والأضاحي"]},{"id":8737,"question":"سماحة الشيخ! كثير من الناس يهتم بالأضحية عن الميت سواء كان هناك وصية أم لم يكن، توجيهكم لو تكرمتم؟","title":"حكم التضحية عن الميت","answer":"الجواب: النبي ﷺ ضحى عنه وعن أهل بيته ولم يفرق بين الحي والميت، فدل ذلك على أنه إذا ضحى تكون الضحية عنه وعن أهل بيته؛ يدخل فيهم أبوه الميت، أو أمه الميتة، أو زوجته، أو أولاده يدخلون في ذلك؛ لأنه ذبحها عنه وعن أهل بيته، وجاء في حديث البراء بن عازب رضي الله عنه عن النبي ﷺ أنه سئل سأله أبو بردة بن نيار وقال: «إني ذبحت عن ولدي» فأقره النبي ﷺ ولم يسأله: هل ولده حي أو ميت، فدل ذلك على أنه إذا ذبح عن بعض أمواته وضحى عن بعض أمواته فذلك لا بأس به، بل هو أمر مشروع لما فيه من الصدقة، والإحسان، والتقرب إلى الله بالنحر، والإحسان إلى الميت بالصدقة، والإحسان إلى الناس باللحوم للفقراء والمحاويج والهدية إلى أصدقائه وأقاربه وجيرانه، لكنها عن الحي آكد، الضحية عن الحي آكد؛ فالسنة ألا يدع الضحية عنه، وإن ضحى عن أهل بيته فهو أفضل، وإن ضحى عن أمواته فحسن، ولا بأس كله طيب، أما إنكار من أنكر الضحية للميت فلا وجه لذلك، هذا الإنكار الذي يفعله بعض الناس عن الميت لا وجه له، إذا ضحى عن الميت فهي قربة وطاعة وخير عظيم. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6891/حكم-التضحية-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_162/16202.mp3","categories":["الهدي والأضاحي"]},{"id":8827,"question":"هذا الأسلوب الذي ظهر أخيرًا -سماحة الشيخ- بالنسبة للتوكيل عن الهدي والأضاحي وما كان من قبل الفدية، رأيكم فيه لو تكرمتم؟","title":"حكم التوكيل في ذبح الهدايا والأضاحي","answer":"الجواب: هذا الذي فعله البنك الإسلامي ومن قبول الوكالات بالتخفيف عن الحجاج والتيسير عليهم أمر طيب، وقد رأينا بحمد الله فوائدها الكثيرة، وهم بحمد الله موثوقون، وعندهم عناية بهذا الأمر، وعندهم مندوبون منا ومن وزارة العدل لمراقبة أعمالهم، فنسأل الله أن ينفع بهم ويعينهم.\nفالأمر في الحقيقة فيه سعة للحجاج؛ لأنه ليس كل أحد يستطيع أن يشتري الهدي وأن يتولى ذبحه وتوزيعه، فهؤلاء يشترونه ويذبحونه ويوزعونه فالحمد لله، لا حرج في ذلك والحمد لله.\nلكن من تيسر له أن يتولى هديه ويذبحه ويوزعه فهذه درجة عليا إذا تيسر فهو الأفضل بلا شك، لكن ما كل أحد يتيسر له ذلك لأجل الزحمة العظيمة. نعم.\nالمقدم: ثم إن الهدي أو الفدية قد تذهب سدى ولا يستفاد منها كما ينبغي؟\nالشيخ: كذلك... قد يكون يذبحها ويتركها، ما عنده عناية بها، فهؤلاء يعتنون بها يوزعون في الداخل وفي الخارج، تحصل المنفعة العظيمة الواسعة الحمد لله.\nالملقي: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6982/حكم-التوكيل-في-ذبح-الهدايا-والاضاحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_164/16403.mp3","categories":["الهدي والأضاحي"]},{"id":8830,"question":"أخونا أحمد الشمراني من حائل يسأل سماحة الشيخ عن شعيرة الأضحية وعن أحكامها، وما حكم من لم يلتزم بها في كل عام؟ وما حكم من يغالي فيها مغالاة تكسر قلوب الفقراء؟","title":"بعض الأحكام المتعلقة بالأضاحي","answer":"الجواب: السنة في الضحية أن يضحي الإنسان عن نفسه وعن أهل بيته حسب التيسير، ولا يكلف الله نفسًا إلا وسعها، إن كان موسرًا ضحى بشاة واحدة عنه وعن أهل بيته، وإن كان معسرًا فلا شيء عليه، ولا ينبغي له بهذا المغالاة والتشديد، بل ينبغي له الرفق في كل الأمور.\nتعيد سؤاله، أعد سؤاله، أعد السؤال.\nالمقدم: يقول: حدثوني عن شعيرة الأضاحي وأحكامها، وما حكم من لم يلتزم بها في كل عام؟ وما حكم من يغالي فيها مغالاة تكسر قلوب الفقراء؟\nالجواب: خير الأمور أوساطها، فالسنة أن يحافظ عليها إذا كان مؤسرًا أن يحافظ عليها ولكن لا تجب، الصحيح أنها لا تجب، إنما هي سنة لفعله صلى الله عليه وسلم، ولا يغالي فيها مغالاة تضر بغيره، ويشدد على الفقراء في ذلك، بل من تيسر له ذلك ضحى وتكفي الشاة الواحدة عنه وعن أهل بيته والحمد لله،ومن شق عليه ذلك فلا حرج، ولا بأس أن يدعها،وأحكامها أنه يأكل ويهدي ويتصدق كما قال تعالى: فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ الْفَقِيرَ [الحج:28] في الهدايا والضحايا يأكل منها ما تيسر يطعم الفقراء، يهدي إلى أقاربه، كل هذا أمر مستحب، وليس فيه تحديد.\nقد رأى بعض أهل العلم التثليث، وأنه يستحب أن يثلث، فيأخذ ثلثًا لنفسه وأهل بيته، وثلثًا يهديه لأقاربه وجيرانه، وثلثًا للفقراء، ولكن هذا ليس بواجب، إذا فعل ذلك فلا بأس، وإن أكل أكثر من الثلث أو أهدى أكثر من الثلث أو أعطى الفقراء غالبها، فلا بأس كله لا بأس، والحمد لله الأمر واسع بحمد الله.\nالمقدم: إذًا: التثليث ليس بحديث؟\nالشيخ: لا، حديث.. ما نعلم فيه حديث صحيح، يروى فيه أحاديث لكن ليست لها أسانيد قائمة.\nثم الضحية لابد فيها أن تكون سليمة كالهدي، يقول النبي ﷺ: أربع لا تجوز في الأضاحي -ومثلها الهدايا-: العوراء البين عورها، والعرجاء البين عرجها، والمريضة البين مرضها، والهزيلة التي لا تنقي هذه لا تجزي في الأضاحي ولا في الهدايا، والعمياء من باب أولى، إذا كانت العوراء لا تجزي؛ فالعمياء من باب أولى، وكذلك المريضة البين مرضها بالجرب أو غيره.\nوهكذا الهزيلة التي لا تنقي لا تجزي في الضحايا.\nوهكذا العرجاء التي ضلعها بين بحيث ما تستطيع المشي مع الصحاح تتأخر عنهم، عرجها واضح.\nوهكذا العضباء التي ذهب أكثر قرنها أو أذنها لأحاديث وردت في ذلك ألا يضحى بها.\nهكذا مقطوع الآلية لا يضحى به، بل يضحي بالشاة السليمة، أما كون بها في الأذن شق أو خرق أو نحو ذلك هذا لا يمنع لكن ترك هذا أفضل إذا تيسر سليمة فهي أفضل، ولكن هذا الخرق والشق لا يمنع الإجزاء تجزي، ولكن السليمة من ذلك أفضل.\nوهكذا التي قطع بعض قرنها، يعني: قليل من قرنها ليس هو الأكثر تجزي ولكن السليمة أفضل.\nوهكذا من قطع طرف أذنها ولكن أكثرها بقي تجزي، ولكن السليمة أفضل، والله المستعان. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6985/بعض-الاحكام-المتعلقة-بالاضاحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_164/16406.mp3","categories":["الهدي والأضاحي"]},{"id":8931,"question":"بارك الله فيكم، رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول أم عبد الله أختنا تقول: إني أريد أن أضحي لوالدتي من حلالها هي؛ لأنها موصية بذلك، فهل يجوز لي أن أمشط شعري وأحني يدي بعد دخول العشر؛ لأني أنا التي سأمسح على الأضحية وأسميها أرجو الرد علي وجزاكم الله خيراً؟","title":"حكم أخذ الوكيل في الذبح من أظفاره وشعره","answer":"الجواب: الأضاحي التي يتولاها الوكيل سواء كان رجل أو امرأة ليس هو مضحياً، فلا حرج عليه أن يأخذ له من شعر شاربه، ويأخذ شعر إبطيه ويقلم أظفاره لا بأس، وهكذا المرأة، لها أن تكد شعرها، ولها أن تقلم أظفارها؛ لأنها غير مضحية وكيل إنما هو وكيل، فالوكيل الذي على السبالة -وكيل الضحايا- الذي يضحي عن أمه أو عن أبيه أو عن أقاربه ليس عليه شيء من ذلك وهكذا المرأة، إنما الذي لا يأخذ هو الذي يضحي من ماله، يتبرع من ماله عن نفسه أو عن أهل بيته أو عن أبيه وأمه من ماله، يتقرب إلى الله بذلك، هذا هو الذي إذا دخلت العشر عشر ذي الحجة لا يأخذ من شعره ولا من أظفاره شيئاً سواء كان رجلاً أو امرأة إذا تبرع من ماله يعني: أخرج من ماله ضحية عنه أو عن أبيه أو عن أمه، أو عنه وعن البيت، هذا هو السنة، فلا يأخذ شيء من شعره ولا من أظفاره ولا من بشرته يعني: جلده، لا يأخذ شيئاً حتى يضحي بعد دخول الشهر؛ شهر ذي الحجة.\nوإذا كان الرجل هو الذي يضحي عن أهل بيته كما هو المشروع، فإن أهله لا يلزمهم الحكم وإنما يلزمه هو، فإذا أراد أن يضحي فلا يأخذ من شعره ولا من أظفاره شيئاً، أما زوجته وبناته وأولاده فلا بأس أن يأخذوا؛ لأنه يضحي هو.\nوأما قول بعض الفقهاء: يحرم على من يضحي أو يضحى عنه، فقولهم: (أو يضحى عنه) ليس عليه دليل، وإنما التحريم يختص بمن يضحي، يعني: بالذي يشتري الضحية من ماله أما الوكيل فلا، وأما زوجة المضحي فلا وهكذا أولاده المضحى عنهم لا حرج عليهم أن يأخذوا من الشعر أو من الظفر. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7089/حكم-اخذ-الوكيل-في-الذبح-من-اظفاره-وشعره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_143/14306.mp3","categories":["الهدي والأضاحي"]},{"id":9040,"question":"السؤال الثاني في رسالة المستمع: عبدالرحمن مولى بخس من الباكستان يقول فيه: كثيراً ما أسمع عن الأضحية، ما حكم الأضحية، وكيفية الأضحية من الإبل؟ أفيدونا أفادكم الله.","title":"حكم الأضحية وكيفيتها","answer":"الجواب: الأضحية سنة، فعلها المصطفى ﷺ، كان يضحي كل سنة بكبشين أملحين، يذبح أحدهما عن محمد وآل محمد، ويذبح الثاني عمن وحد الله من أمته عليه الصلاة والسلام.\nكانت هذه عادته كل سنة، يضحي بذبيحتين، كبشين أملحين من الغنم، فهي سنة مؤكدة مع الاستطاعة، يضحي الإنسان بواحدة عنه وعن أهل بيته عنه وعن زوجته وأبويه ونحو ذلك يعني: عنه وعن أهل بيته وإن كثروا، وليست واجبة، بل هي سنة مؤكدة مع الاستطاعة، واحدة واحدة عنه وعن أهل بيته وإن ضحى بأكثر فلا بأس، وإن كان عاجزاً فلا شيء عليه، إنما هي سنة مؤكدة مع القدرة. نعم.\nالمقدم: ويقول: كيفية الأضحية من الإبل؟\nالشيخ: والإبل يضحى بها أيضاً عن سبعة، والبقرة كذلك، إذا ذبح ناقة أو بعيراً عن سبعة من المسلمين، أو بقرة كذلك عن سبعة من المسلمين فلا بأس، كان المسلمون يضحون بالبدنة والبقرة عن السبعة وهكذا في الهدي في الحج، تذبح البدنة عن سبعة في الهدي والبقرة كذلك عن سبعة، يجتمعون في ذلك ويذبحونها عن أنفسهم في الحج عن الهدي أو في الضحية في بلادهم، ويأكلون ويطعمون، يأكلون منها ويطعمون أصدقاءهم وأقاربهم والفقراء، هذا سنة، المؤمن يأكل من هديته ومن أضحيته، ويطعم ويهدي إلى أصدقائه وأقاربه وجيرانه هذا هو السنة. نعم.","link":"https://binbaz.org.sa/fatwas/7211/حكم-الاضحية-وكيفيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_224/22409.mp3","categories":["الهدي والأضاحي"]},{"id":9096,"question":"السؤال الثاني في رسالة الحاج: فاضل محمد إكرام من الجمهورية التركية يقول فيه: أود معرفة ما حكم الأضحية، وهل هي واجبة على الحاج، فقد ذكر لي بعض العلماء، بأن الضحية ليست على الحاج، وإنما هي على غيره؛ لأنه ليس على الحاج صلاة عيد الأضحى، والأضحية ما يذبح يوم النحر بعد صلاة العيد، أفيدونا أفادكم الله، وهل يؤثم من تركها؟","title":"أحكام الأضحية والفرق بينها وبين الهدي","answer":"الجواب: الأضحية سنة، سنة مؤكدة، كان النبي ﷺ يضحي بكبشين أملحين يوم العيد، أحدهما عن محمد وآل محمد، والثاني عن أمة محمد عليه الصلاة والسلام، فالأضحية سنة لمن تيسر له ذلك فقدر عليه سنة مؤكدة، وقال بعض أهل العلم بوجوبها مع اليسار والقدرة، وظاهر الأحاديث الصحيحة أنها سنة للحجاج وغيرهم، فقد ثبت عنه ﷺ أنه ضحى بكبشين في حجة الوداع عليه الصلاة والسلام، مع ما فعل من ذبح البدن، قد نحر مائة بدنة عليه الصلاة والسلام في حجة الوداع، وضحى بكبشين أملحين فهما سنة، وإذا ضحى الإنسان بواحدة عنه وعن أهل بيته كفى ذلك والحمد لله، وأما الهدايا فهي ما يذبح من أجل الإحرام بالحج والعمرة، يقال له: هدية، ويقال له: دم، يعني: واجب في الحج والعمرة، وهذه الدماء فيها تفصيل، قال الله جل وعلا: فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196].\nفإذا أحرم بالعمرة والحج جميعاً حين جاء إلى مكة أو أحرم بالعمرة وتحلل منها، طاف وسعى وقصر وحل ثم أحرم بالحج، فهذا يقال: عليه هدي، يسمى هدياً، وقد يسميه بعض الناس ضحية، ولكن الاسم المشروع المعروف هو الهدي، فعليه أن يذبح ذلك أيام النحر في يوم العيد، وأيام التشريق هذا الهدي، وهو سبع بدنة أو سبع بقرة أو رأس من الغنم ثني من المعز أو جذع من الضأن، هذا يقال له: هدي التمتع، وهدي القران، أما إذا كان أحرم بالحج وحده، جاء من بلاده وأحرم بالحج فقط، ليس معه عمرة، لبى بالحج وبقي على إحرامه حتى وقف بعرفة وحتى رمى الجمار وطاف وسعى هذا ليس عليه دم؛ لأنه مفرد بالحج، والدم إنما هو على من تمتع بالعمرة إلى الحج، وليس عليه ضحية الضحية سنة ما هي بواجبة، فإذا ضحى في منى أو في مكة هذا سنة، وأما الهدي الذي هو الذبيحة الخاصة، من تمتع بالعمرة إلى الحج أو قرن بينهما فهذا دم واجب يسمى هدي، ويسمى ما يذبح في منى هدي من التطوعات ومن الدماء التي يتطوع بها الإنسان يسمى هدياً، وأما ما يذبح في عيد النحر في المدن والقرى والبوادي فهذا يسمى الضحية، وهي شاة واحدة عن الرجل وأهل بيته، وإن ضحى بسبع بدنة، أو سبع بقرة كفى ذلك والحمد لله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7256/احكام-الاضحية-والفرق-بينها-وبين-الهدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_227/22702.mp3","categories":["الهدي والأضاحي"]},{"id":9097,"question":"وهذه رسالة وصلت إلى البرنامج من الأخ المستمع الحاج آدم عثمان علي من السنغال يقول في رسالته وفي سؤاله الأول: بأنه قدم متمتعاً بالعمرة إلى الحج، ولم يستطع أن يهدي ثم أهل بالحج، فما الحكم في ذلك، وهل يلزمه شيء؟ أفيدونا أفادكم الله.","title":"ما يجب على المتمتع في الحج","answer":"الجواب: إذا كان أهل بالعمرة وفرغ منها وأهل بالحج، فعليه دم، وهو سبع بدنة أو سبع بقرة، أو رأس من الغنم ثني من المعز أو جذع من الضأن، فإذا عجز عن هذا وجب عليه أن يصوم عشرة أيام، ثلاثة في الحج، والأفضل أن تكون قبل عرفة، فإن لم يصمها قبل عرفة صامها أيام التشريق في الحادي عشر والثاني عشر والثالث عشر، فإن لم يتيسر صومه لعجزه عن ذلك فإنه يصومها مع السبعة في بلده، يصوم العشرة جميعاً في بلده، كما قال الله جل وعلا في كتابه العظيم: فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ ذَلِكَ لِمَنْ لَمْ يَكُنْ أَهْلُهُ حَاضِرِي الْمَسْجِدِ الْحَرَامِ [البقرة:196] يعني: من كان من أهل مكة ومن حولها فهذا لا شيء عليه وإنما هذا على ..... يقدم من خارج مكة فهذا عليه .. الهدي إذا أحرم بالحج والعمرة جميعاً، أو أحرم بالعمرة وفرغ منها ثم أهل بالحج في أشهر الحج، فهذا عليه الهدي الذي عرفت وهو سبع بدنة، قد بلغت خمس سنين فأكثر، وهي الثنية أو سبع بقرة قد تم لها سنتان وهي الثنية أو رأس من الغنم، من المعز ثني ومن الضأن يكون جذع قد بلغت ستة أشهر فأكثر، فإن عجز عن ذلك ولم يتيسر له الهدي، وجب عليه أن يصوم عشرة أيام، منها ثلاثة يصومها في الحج قبل عرفات بعد حله من العمرة يصومها، فإن لم يتيسر صومها صامها أيام التشريق، فإن لم يتيسر ذلك صامها مع السبعة في بلاده وليس عليه شيء. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7267/ما-يجب-على-المتمتع-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_227/22710.mp3","categories":["الهدي والأضاحي"]},{"id":9099,"question":"السؤال الثاني يقول فيه: هل يجوز استبدال الهدي بثمنه وتوزيعه على الفقراء عند عودتي إلى بلادي أفيدونا أفادكم الله؟","title":"حكم الاستعاضة عن الهدي بالثمن","answer":"الجواب: لا يجوز، الاستعاضة عن الهدي بالثمن؛ لأن هذا خلاف شرع الله وخلاف ما أوجب الله؛ بل يجب شراء الهدي وذبحه فيأكل منه ويطعم ويتصدق ويهدي والحمد لله، يذبحه في منى أو في مكة وليس له أن يعتاض عن هذا بالثمن في بلده ولا في غير بلده؛ لا يوزعه لا في مكة ولا في بلده، بل يجب عليه الهدي متى قدر، فإن عجز صام عشرة أيام كما تقدم. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7268/حكم-الاستعاضة-عن-الهدي-بالثمن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_227/22711.mp3","categories":["الهدي والأضاحي"]},{"id":9230,"question":"هذه رسالة وصلت إلى البرنامج من المستمع مكاوي أحمد محمد من جمهورية مصر العربية، يقول في رسالته: هل يصح لي أن أقوم بأداء العمرة عن والدتي المتوفية، حيث أني قد أديت العمرة عن نفسي في رمضان هذا العام، وهل يصح لي أن أقوم بأداء العمرة عن والدتي بعد أداء فريضة الحج، أو قبل أدائي لفريضة الحج، أفيدونا أفادكم الله؟","title":"حكم أداء العمرة عن المتوفى","answer":"الجواب: نعم، لا بأس بذلك، بل أنت مأجور، ومشروع لك أن تحسن إلى والدتك بالعمرة قبل الحج أو بعده، وإذا كنت في مكة تحرم من الحل، يعني: خارج مكة، خارج الحرم، من مساجد عائشة التنعيم، أو من الجعرانة، أو غيرهما من الحل، كما أمر النبي ﷺ عائشة رضي الله عنها لما أرادت العمرة بعد الحج أن تحرم من الحل من التنعيم، هكذا السنة فيمن كان في مكة إذا أراد العمرة لنفسه أو لغيره؛ أن يخرج إلى الحل ثم يلبي بعمرة هناك، ثم يدخل فيطوف سبعة أشواط بالبيت ويصلي ركعتين خلف المقام، أو في أي بقعة من المسجد، ثم يسعى بين الصفا والمروة سبعة أشواط، ثم يقصر من رأسه، هكذا العمرة، وأنت مأجور في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7390/حكم-اداء-العمرة-عن-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_233/23310.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":10075,"question":"المستمع صالح علي أبو صفوان بعث برسالة ضمنها جمعاً من الأسئلة من بينها سؤال يقول فيه: هل الأضاحي بالذكور مثل الخراف أو التيوس المخصية، هل يجوز للإنسان أن يضحي بها؟","title":"حكم التضحية بذكور الغنم والمعز والبقر والإبل","answer":"الجواب: نعم الضحية مشروعة بالذكور والإناث من الغنم الماعز والضأن ومن الإبل ومن البقر، كلها سنة مشروعة سواء كان المضحى به من الذكور أو من الإناث، تيس أو كبش أو شاة أو بقرة أنثى أو بقرة ذكر وهكذا البعير وهكذا الناقة كلها ضحايا شرعية، إذا كانت بالسن الشرعي جذع ضأن ثني معز، ثنية من البقر ثنية من الإبل والنبي ﷺ ضحى .. كان يضحي بالكبش بالذكور فالذكر من الضأن أفضل، كبش من الضأن أفضل، كان ﷺ يضحي بكبشين أملحين فهما أفضل من الإناث وإن ضحى بالإناث فلا بأس، أما المعز فالأفضل الأنثى وإن ضحى بالتيس فلا بأس إذا كان قد كمل قد تم سنة فأكثر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8247/حكم-التضحية-بذكور-الغنم-والمعز-والبقر-والابل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30410.mp3","categories":["الهدي والأضاحي"]},{"id":10447,"question":"من أحد الإخوة المستمعين رسالة يقول في أحد أسئلتها: أنا وأخي الأكبر نسكن في بيت واحد وكلانا متزوج، فهل يجب على كل واحد أضحية، أم تكفي واحدة، جزاكم الله خيراً؟","title":"حكم الأضحية الواحدة عن أهل البيت الواحد","answer":"الجواب: السنة واحدة لكما جميعاً، وليست واجبة سنة، الضحية سنة مؤكدة، وإذا ذبحتما واحدة فأنتم أهل بيت واحد، أنتما أهل بيت واحد تكفيكم واحدة، وإن ذبحتم ثنتين فالخير مطلوب والحمد لله، ولكن لا يتأكد ذلك الواحدة تكفي، يقول أبو أيوب : كنا في عهد النبي ﷺ يضحي الرجل منا بالشاة الواحدة عنه وعن أهل بيته فيأكلون ويطعمون، والنبي ﷺ كان يضحي بشاتين إحداهما عنه وعن أهل بيته، والثانية عمن وحد الله من أمته، فالواحدة كافية؛ لأنكما أهل بيت واحد، ولكن لو زدتما فلا حرج.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8615/حكم-الاضحية-الواحدة-عن-اهل-البيت-الواحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_318/31807.mp3","categories":["الهدي والأضاحي"]},{"id":10539,"question":"له فقرة أخرى سماحة الشيخ عبد العزيز يقول: بالنسبة لحكم ذبح الأضحية أو الذبيحة بالسكين الكهربائية؟","title":"حكم ذبح الأضحية وغيرها بالسكين الكهربائية","answer":"الجواب: ما نعرف السكين الكهربائية، إذا كانت السكين الكهربائية مع التسمية تقطع الحلقوم والمريء يحصل بها الذبح فلا بأس، إذا كانت سكين حقيقية تقطع الحلقوم والمريء سواء بالكهرب أو باليد مع التسمية، يسمي الله ويفعل فلا بأس.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8714/حكم-ذبح-الاضحية-وغيرها-بالسكين-الكهرباىية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28411.mp3","categories":["الهدي والأضاحي"]},{"id":10676,"question":"إذا أراد الإنسان أن يحج أو يطوف أو يتصدق أو يذبح أضحية عن والديه، هل يقول: اللهم إن هذه عن والدي، بمعنى آخر: هل يظهر النية، أم تكون في القلب؟","title":"حكم الحج والطواف والتصدق والأضحية عن الوالدين","answer":"الجواب: الضحية الأفضل له يسمي، يقول: باسم الله والله أكبر عن والدي، أو اللهم تقبل مني عن والدي هذا أفضل، وإن اكتفى بالنية فلا بأس ولا حرج، النبي ﷺ لما ضحى قال: اللهم تقبل من محمد وآل محمد، أما أنه يطوف عنهم أو يصلي عنهم هذا غير مشروع، لا يطوف عن أحد ولا يصلي عن أحد، إنما يطوف عن نفسه ويصلي عن نفسه، ويدعو لوالديه في طوافه أو في صلاته، وهكذا لا يصوم عن أحد، إلا إذا كان عليه صيام فريضة فصام عنه وليه كأخيه أو أبيه أو نحو ذلك فلا بأس، كما قال عليه الصلاة والسلام: من مات وعليه صيام صام عنه وليه، أما أن يتطوع عنه بالصوم أو بالصلاة فهذا لا أصل له، وهكذا الطواف ليس عليه دليل، فالأفضل أن لا يطوف عن أحد. نعم إذا حج حجاً كاملاً عن أبيه أو أمه أو غيرهما من أمواته وأقاربه، الأموات أو العاجزين فلا بأس بذلك، وهكذا العمرة؛ لأنه ورد في الأدلة ما يدل على ذلك، أما كونه يصلي عن فلان، أو يطوف عن فلان، أو يصوم عن فلان تطوعاً فهذا لا دليل عليه. ولا ينبغي فعله، لكن الصدقة عن الأموات والأحياء طيبة نافعة، الصدقة طيبة نافعة، كونه يدعو لهم، يستغفر لهم، يحج عن الميت، عن العاجز، يعتمر كل هذا طيب، يؤدي الدين عن المدين، كل هذا نافع. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8868/حكم-الحج-والطواف-والتصدق-والاضحية-عن-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33018.mp3","categories":["إهداء القرب للميت","الهدي والأضاحي"]},{"id":11641,"question":"من المستمع علي محمد علي من جمهورية مصر العربية، والمقيم حاليًا في المملكة يقول: حيث من الله علي بأداء فريضة الحج لهذا العام قارنًا، ونظرًا لظروفي المادية لم أتمكن من تسديد ثمن الهدي المفروض علي، وسألت بعض العلماء عن ذلك، فأجابني بأن أصوم ثلاثة أيام في الحج، وسبعة عند الرجوع، وذلك في خلال شهر ذي الحجة، وفعلًا قمت بصيام الثلاثة الأولى في الحج، وعند عودتي إلى عملي لم أستطع صيام السبع الأخرى لظروف عملي الشاقة، فما حكم الشرع في ذلك، وماذا يجب علي عمله إزاء هذا الموضوع؟ جزاكم الله خيرًا.","title":"حكم من صام ثلاثة أيام في الحج وعجز عن السبعة","answer":"الجواب:  هذه الفتوى صحيحة، إذا عجزت عن الدم؛ تصم عشرة أيام، ثلاثة أيام في الحج، وسبعة إذا رجعت إلى أهلك، لكن لا يتعين في ذي الحجة، ما هو بلازم، ليس لها حد محدود، تصومها متى تيسر، في محرم في صفر في ربيع حسب التيسير، تصوم السبعة مجتمعات أو متفرقات، لا بأس، لكن لا يجوز لك التساهل، بل يجب أن تصومها، وأن تحرص في ذلك عند التيسر، أما إذا شغلت عنها بأسباب تمنعك؛ فلا بأس، لكن عليك أن تتحين الأوقات التي تستطيع فيها، ولو مفرقة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9826/حكم-من-صام-ثلاثة-ايام-في-الحج-وعجز-عن-السبعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38913.mp3","categories":["الهدي والأضاحي"]},{"id":11995,"question":"هل يجوز للمرأة أن تمشط شعرها في عشر ذي الحجة؟","title":"حكم مشط المرأة شعرها في عشر ذي الحجة","answer":"الجواب:  إذا كان لا تضحي لا بأس، أما إذا كانت تضحي، تمشطه، لكن من دون قطع، لا تقطع الشعر، تمشطه، تنقضه، وتمشطه، لكن من دون كد، من دون قطع شعر، إذا كانت تضحي.  أما إذا كان لا تضحي؛ فالحمد لله، تكده تمشطه، لكن مشطه ونقضه لا بأس به، حتى ولو كانت بتضحي، بس لا تعمد قطع الشعر، لا تعمد قطع الشعر، حتى تضحي، سواءً كانت تضحي عن نفسها، أو عن أبيها وأمها، أو عن زوجها، والسنة أن تضحي عن نفسها، وعن أهل بيتها، وتجمعهم جميعًا عنها وعن والديها، عن زوجها وأولادها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10180/حكم-مشط-المراة-شعرها-في-عشر-ذي-الحجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43109.mp3","categories":["الهدي والأضاحي"]},{"id":12120,"question":"كان علي أن أصوم في الحج عشرة أيام لعدم استطاعتي تقديم الهدي، فلم أستطع أن أصوم أيامًا في مكة، بل صمتها جميعًا بعدما عدت إلى أهلي، فهل ما فعلته صحيح، صاحب هذا السؤال هو المستمع (ر. ع) .. من الرياض؟","title":"حكم صيام العشرة الأيام في البلد لمن عجز عن الهدي","answer":"الجواب: الواجب أن تصوم ثلاثة أيام في الحج قبل عرفة، أو أيام التشريق، فإذا لم يتيسر ذلك لعجز، أو مرض، أو غير ذلك صمت العشرة جميعًا في أهلك وبلدك، والحمد لله، ولا شيء  عليك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10305/حكم-صيام-العشرة-الايام-في-البلد-لمن-عجز-عن-الهدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43805.mp3","categories":["الهدي والأضاحي"]},{"id":12152,"question":"ننتقل إلى قضية أخرى من القضايا التي تسأل عنها هذه المستمعة، إذا تسأل سماحتكم فتقول: نسمع أناسًا عند الذبح يسمون بالله، ويكبرون، ولكنهم لا ينطقون بالشهادة، فهل يلزم النطق بالشهادة عند الذبيحة، أو لا يلزم؟","title":"ما يقال عند ذبح الأضحية وغيرها","answer":"الجواب:  السنة عند الذبح: باسم الله والله أكبر ما يحتاج شهادة، (باسم الله والله أكبر) ثم يذبح: كان النبي ﷺ إذا أراد أن يذبح يقول: باسم الله، والله أكبر ثم يذبح الذبيحة، وإن كانت ضحية يقول: اللهم عن فلان ابن فلان، أو عن فلانة أفضل، أو عقيقة: وهي ...... التي تذبح عن المولود. يقول: اللهم عن ولدي فلان، أو بنتي فلانة، ما فيه بأس، هذا مشروع، ولكن يقول عند الذبح: (باسم الله والله أكبر) ثم يجر السكينة على الذبيحة، أو يطعن في اللبة إن كان الذبيحة من الإبل. يطعنها في اللبة بالحربة، وإن كان من البقر الغنم ذبحها على جنبها الأيسر، ذبحها بالسكين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10337/ما-يقال-عند-ذبح-الاضحية-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_441/44102.mp3","categories":["الهدي والأضاحي"]},{"id":12414,"question":"يسأل عن حكم صيد الطيور في الأشهر الحرم؟","title":"حكم صيد الطيور في الأشهر الحرم","answer":"الجواب:  الصواب أن الأشهر الحرم لا يحرم فيها الصيد، إنما الصيد يحرم على المحرم بالحج والعمرة، أو في أرض الحرم المكي، أو المدني، وأما الأشهر الحرم: رجب، وذو القعدة، وذو الحجة، والمحرم هذه لا يحرم فيها الصيد، وإنما اختلف العلماء هل يحرم فيه القتال، أم لا، وأما الصيد فلا يحرم فيها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10614/حكم-صيد-الطيور-في-الاشهر-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40202.mp3","categories":["الهدي والأضاحي","الفدية وجزاء الصيد"]},{"id":12602,"question":"هل يجوز لرجل لا يملك ثمن الأضحية حاضرًا، هل يجوز له الاستلاف، لشراء الأضحية، ثم يقوم بتسديد هذا المبلغ لصاحبه فيما بعد، علمًا بأن لهذا الرجل أشجارًا تنتج فواكه يتكسب منها؟","title":"حكم الاستدانة لأجل شراء الأضحية","answer":"الجواب:  نعم يستحب له، يستقرض، ويستدين، ويضحي، إذا كان خلفه ما يوفي منه، عنده ما يوفي منه.... الضحية سنة ولو بالاستدانة، إذا كان عنده ما يقضي ويوفي منه. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10823/حكم-الاستدانة-لاجل-شراء-الاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41411.mp3","categories":["الهدي والأضاحي"]},{"id":12617,"question":"هل يجوز لرجل لا يملك ثمن الأضحية حاضرًا، هل يجوز له الاستلاف، لشراء الأضحية، ثم يقوم بتسديد هذا المبلغ لصاحبه فيما بعد، علمًا بأن لهذا الرجل أشجارًا تنتج فواكه يتكسب منها؟","title":"حكم الاستدانة لأجل شراء الأضحية","answer":"الجواب:  نعم يستحب له، يستقرض، ويستدين، ويضحي، إذا كان خلفه ما يوفي منه، عنده ما يوفي منه.... الضحية سنة ولو بالاستدانة، إذا كان عنده ما يقضي ويوفي منه. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10823/حكم-الاستدانة-لاجل-شراء-الاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41411.mp3","categories":["الهدي والأضاحي"]},{"id":12738,"question":"أنا مقيم في مكة، وفيما إذا أذن لي، وقمت بأداء الحج، وأنوي الحج تمتع، فهل علي فدية؟","title":"حكم الهدي على من تمتع بالعمرة وهو من أهل مكة","answer":"الجواب:  إذا كنت مستوطنًا في مكة؛ فليس عليك فدية؛ لأن أهل مكة هم حاضروا المسجد الحرام، فإذا تمتعوا بالعمرة إلى الحج؛ فليس عليهم هدي، أما إن كنت مقيمًا للعمل، ولست من أهل مكة، إنما أقمت للعمل، ثم اعتمرت في أشهر الحج بعد رمضان، وحججت في ذلك العام؛ فإنك تفدي، هذا هو الأحوط لك؛ لأنك لست من حاضري المسجد الحرام بالمعنى الكامل، وإنما أنت مقيم لعارض، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10952/حكم-الهدي-على-من-تمتع-بالعمرة-وهو-من-اهل-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_418/41809.mp3","categories":["الهدي والأضاحي"]},{"id":13004,"question":"ننتقل إلى رسالة بعث السائل سعد محمد من الرياض يقول: سماحة الشيخ! امرأة أرملة توفي زوجها، ومعها ستة أطفال قصر، وأيضًا لها ابن من زوجة أخرى، وهذا الابن موظف ومتزوج ولديه أطفال، ويسكن في شقة، وعمته والأطفال في شقة أخرى، ولكن في عمارة واحدة،  هل تجزي عنهم أضحية واحدة؟","title":"من أحكام الأضحية","answer":"الجواب: لا، كل واحد يضحي، هو يضحي عن نفسه وأهل بيته، وأنتم تضحون عن أنفسكم مع القدرة؛ لأنها سنة، ما هي بواجبة، مع القدرة كل واحد يضحي لنفسه وأولاده، ومن تحت يده، والحمد لله، سنة عن الرجل وأهل بيته، المرأة وأهل بيتها، فهو يضحي عن نفسه في شقته وأهل بيته، وأنتم وحدكم، نعم، السنة كل واحد يضحي؛ لأنكم في بيتين مستقلين، نعم. المقدم: شكر الله لكم -يا سماحة الشيخ- وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11221/من-احكام-الاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50417.mp3","categories":["الهدي والأضاحي"]},{"id":13141,"question":"رسالة خطها خط أهل المغرب العربي، وصاحبها يقول: محفوظ بن محمد محمود يسأل ويقول: مسلم مقيم ببلد غير إسلامي، وإن ذبح الأضحية قد لا يجد محتاجًا يطعمه منها، فهو يرى أن يرسل بثمنها لفقراء المسلمين، أو لتذبح بأرضهم، فما تعليقكم على هذا، أفيدونا جزاكم الله خيرًا؟","title":"حكم ذبح الأضحية في غير مكان المضحي أو إرسال قيمتها","answer":"الجواب:  لا مانع في ذلك إن أرسلها تذبح هناك، هذا حسن بواسطة الثقات، وإن أرسل قيمتها؛ فلا بأس، لكن كونه يذبحها عنده إذا تيسر من يأكلها من أصحابه وإخوانه أفضل، يقيم السنة في محله في الأقليات الإسلامية، ويهدي إلى إخوانه الطلبة والمسلمين، ويهدي منها للكفار، ما في بأس إذا كانوا غير محاربين للإسلام.. أمن وعدم محاربة للإسلام؛ لأنها صدقة تطوع. وإن أرسلها للفقراء في أفريقيا، أو المجاهدين في الأفغان، أو أرسل قيمتها؛ فلا بأس إذا ما كان عنده من يأكل منها ويستفيد منها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11395/حكم-ذبح-الاضحية-في-غير-مكان-المضحي-او-ارسال-قيمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47416.mp3","categories":["الهدي والأضاحي"]},{"id":13142,"question":"من مهد الذهب المستشفى رسالة وصلت من أحد الإخوة المستمعين يقول: (أ. غ. ع. أ) أيضًا سؤاله عن الأضاحي، يقول عن الأضحية الواحدة: هل تكفي، أو تجزئ عني، وعن والدي، علمًا بأني متزوج، ولي أسرة، وطبعًا الوالد له كذلك؟","title":"هل تجزئ الأضحية عن الولد المتزوج وأبيه؟","answer":"الجواب:  إذا كنتما في بيت واحد؛ ذبيحة واحدة تكفي عنكما، السنة عنك وعن أبيك وزوجاتكما وأولادكما، أما إذا كنت في بيت مستقل، وأبوك في بيت مستقل؛ فالسنة أن يضحي كل واحد منكما عن نفسه وأهل بيته؛ لقوله ﷺ في الحديث.. لأنه ﷺ كان يضحي بشاتين.. بكبشين -عليه الصلاة والسلام- \"كان يضحي بكبشين أملحين أحدهما عنه وعن أهل بيته والثاني عن أمة محمد، عليه الصلاة والسلام\". فالحاصل: أنك إذا كنت مستقلًا وهو مستقل؛ السنة أن يضحي كل واحد عن نفسه وأهل بيته، أما إذا كنتم في بيت واحد مجتمعون، حالكم واحدة؛ تكفي واحدة، وإن ضحيتم بأكثر؛ فلا بأس، الأمر في هذا واسع، قال أبو أيوب الأنصاري  -الصحابي الجليل-: كنا في عهد النبي ﷺ نضحي بالشاة الواحدة، يضحي بها الرجل عنه، وأهل بيته نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11396/هل-تجزى-الاضحية-عن-الولد-المتزوج-وابيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47417.mp3","categories":["الهدي والأضاحي"]},{"id":13238,"question":"بعد ذلك ننتقل إلى رسالة بعثت بها السائلة أم عبدالرحمن تقول: نرجو من سماحتكم الإجابة على هذا  إذا حج الرجل ومعه زوجته ووالدته، هل يجب أن يضحي عن كل واحد بأضحية مفردة، أم يكفي أضحية واحدة عنهم جميعًا، هذا بالنسبة للحاج الذي نوى نسك الإفراد؟","title":"من أحكام الأضحية والهدي","answer":"الجواب: السنة أضحية واحدة عنهم جميعًا في البلد، أو في أي مكان، لو كان في البيت، في البلد، في البيت عشرون، أو أكثر من الزوجة والأولاد، وغيرهم ضحية واحدة تكفي عن الرجل، وأهل بيته، النبي ﷺ «كان يضحي بشاة واحدة عنه وعن أهل بيته» وأهل بيته تسع نساء غير ما يتعلق بالخدام والذرية. فالمقصود: أن السنة عن أهل البيت ضحية واحدة، وإن ضحوا بأكثر؛ فلا بأس، لكن السنة عنهم ضحية واحدة، هذا هو السنة، سبع بدنة، أو سبع بقرة، أو شاة، والشاة أفضل. أما الهدي الذي يسمونه الفدي، وهو هدي التمتع، والقران هذا عن كل واحد فدي إذا كان متمتعًا بالعمرة إلى الحج، أو قارنًا بين الحج والعمرة، فهذا كل واحد يذبح، كل واحد يذبح شاة واحدة، أو سبع بدنة، أو سبع بقرة، فدية للتمتع، يسمى هدي التمتع، أو هدي القران، هذا لا يسمى ضحية، هذا يسمى هدي، هدي التمتع.  فإذا كان الإنسان وزوجته، وأمه قد أحرموا بالعمرة مع الحج، أو تمتعوا بالعمرة، ثم أحرموا بالحج كل واحد يهدي ذبيحة، أو سبع بدنة، أو سبع بقرة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11519/من-احكام-الاضحية-والهدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51304.mp3","categories":["الهدي والأضاحي"]},{"id":13239,"question":"تقول السائلة: ماذا عن نسكي القران والتمتع، هل يضحى فيهما؟","title":"حكم الهدي للمتمتع والقارن","answer":"الجواب:  تقدم، التمتع والقران فيهما الفدية ما يسمى ضحية، يسمى هدي، يسمى فدية، يسمونه العامة فدي، و.. الفدية، وسماه الله الهدي، هدي التمتع، قال -جل وعلا-: فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196]. فعلى من أحرم بالعمرة في أشهر الحج، ثم حج، أو أحرم بهما جميعًا، بالحج والعمرة جميعًا، وكمل؛ عليه أن يهدي، يذبح في يوم العيد، أو في أيام منى ذبيحة عنه، أو سبع بدنة، أو سبع بقرة، وإن كان معه زوجته ذبيحتان، وإن كان معه أبوه ثلاث، عنه واحدة، وعن الزوجة واحدة، وعن أبيه واحدة، وهكذا إذا كان معهم أولاد قد أحرموا معهم، عن كل واحد ذبيحة إذا كانوا متمتعين أو قارنين، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11521/حكم-الهدي-للمتمتع-والقارن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51305.mp3","categories":["الهدي والأضاحي"]},{"id":13320,"question":"السائل يقول: شخص حج متمتعًا، وقام بجميع المناسك -مناسك الحج- ولم يفد لظروفه، وهو مقيم في المملكة، ولم يستطع الصيام لظروفه الصحية، فهل يسقط عنه ذلك، جزاكم الله خيرًا.","title":"حكم من حج متمتعًا وعجز عن الهدي والصيام","answer":"الجواب: يجب عليه الهدي، هدي التمتع، فإذا عجز عن هدي التمتع، وعجز عن الصيام؛ يبقى معلقًا في ذمته حتى يستطيع، يبقى معلقًا في ذمته مثل قضاء رمضان، يبقى معلقًا حتى يستطع الهدي فيهدي أو الصوم فيصوم؛ لأن الله -جل وعلا- أوجب عليه الهدي، قال: فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ [البقرة:196] فعليه أن يتقي الله، وأن يراقب الله، فإن استطاع الهدي؛ أرسل إلى مكة، وذبحها هناك، أو وكل من يشتريه له، ويذبحه هناك، فإن عجز، واستمر العجز عن الهدي؛ فيصوم ثلاثة أيام في الحج، وسبعة إذا رجع، فإن تأخر الصيام؛ صامها كلها عند أهله. المقصود: أنه ليس له أن يتساهل، بل عليه إما أن يهدي إن قدر، أو يصوم، فإذا عجز عنهما؛ تبقى الفدية في ذمته حتى يتيسر له ذلك. فإن مات ولم يتيسر له ذلك؛ قضي من تركته إن كان له تركة، يشترى من تركته، ويفدى عنه؛ لأنه دين في ذمته. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11606/حكم-من-حج-متمتعا-وعجز-عن-الهدي-والصيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52203.mp3","categories":["الهدي والأضاحي"]},{"id":13579,"question":"السائل في ثاني أسئلته يقول سماحة الشيخ: ذهبت من مكة إلى المدينة، وصليت العيد في المدينة، وعدت إلى مكة ثاني يوم العيد، وأنا أريد الحج، هل عليَّ هدي؟","title":"الهدي يجب على الحاج المتمتع","answer":"الجواب: هذا فيه تفصيل: إذا كنت أديت عمرة في أشهر الحج بعد رمضان، ثم حججت ذلك العام؛ عليك الهدي، ولو رحت إلى المدينة، ورجعت، عليك الهدي، إذا كنت أديت العمرة بعد رمضان، ثم حججت من ذلك العام؛ فأنت متمتع، وعليك الهدي ذبيحة واحدة من الغنم، أو سبع بدنة، أو سبع بقرة؛ لأنك -والحال ما ذكر- تسمى متمتعًا. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11920/الهدي-يجب-على-الحاج-المتمتع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_533/53306.mp3","categories":["الهدي والأضاحي"]},{"id":13731,"question":"يقول هذا السائل (محمد . أ. أ) الدمام سؤالي في الأضحية: أردت أن أضحي في العام الماضي ببقرة، فقالوا لي: بأن الكبش أفضل، هل ورد أحاديث تفيد بأن الكبش في ذلك أفضل يا سماحة الشيخ؟","title":"الدليل على أفضلية الأضحية بالكبش","answer":"الجواب: نعم، النبي ﷺ ضحى بكبشين، النبي كان يضحي بالغنم -عليه الصلاة والسلام- فإذا تيسر بالغنم؛ فهو أفضل، وإن ضحى بالبدنة، أو بالبقرة؛ لا بأس، الصحابة ضحوا بهذا وهذا، والنبي ﷺ أهدى البدن في حجة الوداع مائة بدنة تطوعًا، فإذا ضحى بإبل، أو ببقر؛ فلا بأس، لكن الغنم أفضل إذا تيسرت. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12102/الدليل-على-افضلية-الاضحية-بالكبش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54517.mp3","categories":["الهدي والأضاحي"]},{"id":13883,"question":"السائلة من القصيم تقول: يقول بعض الناس بأن تسريح الشعر في العشر الأواخر محرم، فهل هذا صحيح؟","title":"حكم تسريح المرأة شعرها في عشر ذي الحجة","answer":"الجواب: إذا كانت تبي تضحي لا تقص الشعر، لا تكده كد يقطعه، ... تريد تضحي وإلا فلا حرج، إذا كان ما هي مضحية لا حرج عليها.","link":"https://binbaz.org.sa/fatwas/12286/حكم-تسريح-المراة-شعرها-في-عشر-ذي-الحجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50617.mp3","categories":["الهدي والأضاحي"]},{"id":13980,"question":"مستمع مصري مقيم في العراق هو الأخ سيد إبراهيم مرعي بعث بسؤالين، يقول: إنني حجيت بيت الله الحرام في عام ثمانية وسبعين ميلادية، وأكملت جميع نسك الحج، ونسيت أن أصوم ثلاثة أيام خلال فريضة الحج، وسبعة أيام بعد أداء الفريضة.الشيخ: أعد.المقدم: يقول: إنني حجيت بيت الله الحرام في عام ثمانية وسبعين ميلادية، وأكملت جميع نسك الحج، ونسيت أن أصوم ثلاثة أيام خلال فريضة الحج، وسبعة أيام بعد أداء الفريضة، علمًا بأنني لم أعلم ولم أعرف بصيام هذه الأيام، فهل أصوم هذه الأيام، أم أن لها كفارة؟ أفيدوني جزاكم الله خيرًا.","title":"ما يجب على من حج ونسي صيام العشرة أيام؟","answer":"الجواب: إذا كنت حين أحرمت من الميقات لبيت بالعمرة والحج جميعًا، أو بالعمرة ثم لبيت بالحج بعدها؛ فعليك أن تصوم هذه الأيام، إلا إذا استطعت الهدي شاة، يعني: وهو شاة من الغنم: جذع ضأن أو ثني من المعز، توكل من يذبحه في مكة في الحرم الشريف للفقراء؛ فإن ذلك هو الواجب عليك الهدي، فإذا كنت عاجزًا ما تستطيع رأسًا من الغنم يذبح في مكة، ولا سبع بدنة، ولا سبع بقرة يذبح في مكة؛ فإنك تصوم عشرة أيام في بلدك، ويكفيك ذلك.\nأما إن كنت إنما لبيت بالحج فقط، أحرمت بالحج فقط مفردًا؛ فليس عليك لا صيام ولا هدي؛ لأن الهدي إنما يجب على من تمتع بالعمرة إلى الحج، فأما المفرد الذي لم يحرم إلا بالحج فقط، فإنه لا شيء عليه عند جميع أهل العلم. نعم.\nالمقدم: جزاكم الله خيرًا، إذًا الصيام ليس على كل حاج والحالة هذه.\nالشيخ: على من أحرم بالعمرة والحج جميعًا، أو بالعمرة ثم ..... الحج.. أو بالعمرة، يعني: وحل منها ثم أحرم بالحج، يعني: المتمتع والقارن.\nالمقدم: المتمتع والقارن.\nالشيخ: اللي أحرم بالعمرة من الميقات، ثم حل منها وأحرم بالحج في عامه في أشهر الحج، أو أحرم بهما جميعًا، أو أحرم بعمرة وحدها ثم في أثناء الطريق لبى بالحج معها، هذا هو يسمى قارن، والذي حل منها وتمتع بها، ثم أحرم بالحج في وقته في اليوم الثامن مثلاً؛ هذا يسميه العلماء متمتعًا، هؤلاء هم الذين عليهم الهدي، الذي أحرم بالعمرة مع الحج جميعًا، أو بالعمرة ثم أدخل عليها الحج، أو بالعمرة وحل منها طاف وسعى وقصر بعد رمضان وحل منها، ثم أحرم بالحج في وقته في سنته، نعم، هذا هو الذي يسمى متمتعًا حتى القارن يسمى متمتع، هذا هو الذي عليه الهدي، وهو رأس من الغنم: إما جذع الضأن، أو ثني من المعز، أو سبع بدنة، أو سبع بقرة يذبح في مكة في الحرم الشريف، ويوزع على فقراء الحرم. نعم.\nالمقدم: إذًا الصيام ليس في كل حال من الأحوال.\nالشيخ: لا، لا.\nالمقدم: في حال دون حال.\nالشيخ: الصيام على المتمتع والقارن إذا عجزا عن الهدي.\nالمقدم: إذا عجزا عن الهدي.\nالشيخ: إن عجزا عن الهدي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12406/ما-يجب-على-من-حج-ونسي-صيام-العشرة-ايام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_606/60603.mp3","categories":["الهدي والأضاحي"]},{"id":14187,"question":"سمعت من بعض الناس أنه لا يجوز للإنسان قص أظافره في العشر الأول من ذي الحجة هل ما سمعته صحيح؟","title":"هل تُقص الأظافر إذا دخلت عشر ذي الحجة؟","answer":"الجواب: إذا كان يريد الضحية فإنه لا يقص أظفاره ولا شعره ولا بشرته حتى يضحي بعد دخول الشهر، لما ثبت في صحيح مسلم عن أم سلمة رضي الله عنها عن النبي ﷺ أنه قال: إذا دخل شهر ذي الحجة وأراد أحدكم أن يضحي فلا يأخذ من شعره ولا من أظفاره ولا من بشرته شيئًا. أما إذا كان لا يضحي فلا شيء عليه، يقص في عشر ذي الحجة وغيرها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12640/هل-تقص-الاظافر-اذا-دخلت-عشر-ذي-الحجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48603.mp3","categories":["الهدي والأضاحي"]},{"id":14336,"question":"المستمعة لبرنامجكم نور على الدرب أم عادل بعثت تسأل وتقول: ماذا يعمل من ينفق على روح الميت بأضحية وما أشبه ذلك مثل العشاء بذبح شاة أو بقرة؟ وما حكم ذلك لغير الميت؟ وما يقتضي عمله لغير الميت؟ وهل يصح تكرار الأضحية للعيد الكبير كل سنة؟ وكم مرة تكرر في العمر؟ هذه بعض أسئلتها لو تكرمتم شيخ عبد العزيز.","title":"حكم الأضحية عن الحي والميت والذبح للصدقة","answer":"الجواب: ليس لهذا حد، فله أن يضحي عن الميت، وله أن يضحي عن الحي من أهل بيته كأن يذبح ضحية عنه وعن والديه الأحياء وعن أهل بيته من زوجة وأولاد، وله أن يضحي عن الميت من أبيه أو أمه أو خالته أو خاله أو نحو ذلك، وليس لذلك حد، إذا ضحى كل سنة فهذا حسن، والضحية سنة كل سنة، النبي كان يضحي كل سنة عليه الصلاة والسلام ضحيتين: إحداهما عنه وعن أهل بيته، والثانية عمن وحد الله من أمته عليه الصلاة والسلام. وإذا تصدق غير الأضحية ذبح في رمضان أو في غيره ناقة أو بقرة أو شاة أو عدد أكثر نوى بذلك الصدقة عن نفسه أو عن والديه الحيين أو الميتين أو عن غيرهم صدقة يطلب بها ثواب الله ويتصدق بها عن الفقراء والمساكين كل ذلك نافع، كل ذلك فيه أجر كثير، يقول النبي ﷺ: الصدق تطفئ الخطيئة كما يطفئ الماء النار والله يقول سبحانه: وَأَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ إِنْ كُنتُمْ تَعْلَمُونَ [البقرة:280]، ويقول جل وعلا: الَّذِينَ يُنفِقُونَ أَمْوَالَهُمْ بِاللَّيْلِ وَالنَّهَارِ سِرًّا وَعَلانِيَةً فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ [البقرة:274]. فالصدقة بالمال، بالنقود والذبائح والملابس والأطعمة كلها طيبة إذا قصد بها وجه الله والتقرب إلى الله  عن الأحياء والأموات في رمضان وفي غيره، وهكذا الضحية في أيام الضحية في يوم عيد النحر وأيام التشريق هذه الضحايا مشروعة للمسلمين، يضحي عن نفسه وأهل بيته، وعمن شاء من إخوانه وأحبابه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12829/حكم-الاضحية-عن-الحي-والميت-والذبح-للصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_623/62308.mp3","categories":["الهدي والأضاحي"]},{"id":14584,"question":"عن الأضحية يسألون: متى يكبر على الذبيحة التي تذبح في العيد؟ ومتى تذبح؟ هل يصح أن تظل لمدة أسبوع أم تذبح مباشرة في ذلك اليوم، أم كيف ذلك؟ وما هي شروط الذبيحة كون بعضها كسراء، أو عوراء، أو كبيرة في سنها، ماذا في ذلك؟ أفيدونا عن هذه المواضيع، جزاكم الله خيرًا.","title":"وقت ذبح الأضحية والعيوب التي لا تجزئ معها","answer":"الجواب: السنة عند الذبح أن يقول: باسم الله، والله أكبر، سواءً ضحية أو للأكل، باسم الله، والله أكبر، في جميع الأوقات، يقول الذابح عند الذبح: باسم الله، والله أكبر عندما يحرك يده للذبح، هذا السنة.  أما الضحية فتذبح في أربعة أيام، يوم العيد؛ يوم عيد النحر والأيام الثلاث التي بعدها، أربعة، الجميع أربعة على الصحيح من أقوال العلماء، كلها أيام ذبح، يوم العيد واليوم الحادي عشر والثاني عشر والثالث عشر إلى غروب الشمس، هذه الأيام الأربع كلها أيام ذبح. وأما الضحية المجزئة فقد بيَّنها النبي ﷺ، قال -عليه الصلاة والسلام-: أربعة لا تجوز في الأضاحي: العوراء البيِّن عورها، والعرجاء البيِّن ضلعها، والمريضة البيِّن مرضها، والهزيلة التي لا تنقي ليس فيها نقي، ليس فيها مخ، هزيلة ضعيفة، هذه الأربع لا تجزئ في الأضاحي، ولا في الهدايا وقت الحج، ولا في العقيقة، التي تذبح عن المولود يوم السابع، كل هذه لا تجزئ فيها، أربع يقول ﷺ: أربع لا تجوز في الأضاحي: العوراء البيِّن عورها أما إذا كان عورها ما هو بيِّن، في عينها شيء لكن ما هو ببيِّن لا يضر لا يمنع والعرجاء البيِّن ضلعها أما إذا كان عرجها يسير يعفى عنه المريضة البيِّن مرضها إن كان مرضها يسير ما يبيِّن يعفى عنها الهزيلة التي لا تنقي ليس فيها نقي، يعني: هزيلة ضعيفة القوة، هزيلة من جهة عدم المخ فيها، هذه الأربع لا تجزئ في الأضاحي، ولا في الهدايا في وقت الحج، ولا في العقيقة عن المولود، ولا في النذور، من نذر أن يذبح شاة أو بقرة أو نحو ذلك، لا بد أن تكون سليمة من هذه العيوب. وهناك نوع خامس وهو العضباء التي ذهب أكثر قرنها أو أذنها، الصحيح أنها لا تجزئ؛ لأنه ثبت عن النبي ﷺ النهي عن الضحية بالعضباء، وهي التي ذهب أكثر قرنها أو أذنها، أو ذهب القرن كله والأذن كلها، هذه خامسة، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13081/وقت-ذبح-الاضحية-والعيوب-التي-لا-تجزى-معها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_63504.mp3","categories":["الهدي والأضاحي"]},{"id":14585,"question":"يعتقد بعض الناس -سماحة الشيخ- أن الناس لا يذبحون إلا بعد أن يذبح إمامهم الأضحية، هل هذا صحيح؟","title":"هل يلزم ذبح الأضحية بعد ذبح الإمام؟","answer":"الجواب: الصواب أنه لا يلزم، متى صلي صلاة العيد، جازت التضحية يضحون الناس إذا كان في البلد بعد صلاة العيد، وإذا كان في البوادي، أو في منى بعد ارتفاع الشمس قيد رمح يذبح، إذا كان ما عندهم صلاة كالبوادي، وأهل منى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13082/هل-يلزم-ذبح-الاضحية-بعد-ذبح-الامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_63505.mp3","categories":["الهدي والأضاحي"]},{"id":15022,"question":"هذه رسالة وردتنا من المستمع: (م. م. ع) يقول في رسالته هذه: العمال والمتعاقدون الذين وفدوا إلى مكة للإقامة لمدة سنة، أو أكثر، وبعضهم أحضر معه عائلته، فهل يعتبرون من أهل مكة في موضع الهدي؟ وقد تكون العمرة التي أتوا بها في أشهر الحج، أحرموا لها من التنعيم، فهل يلزمهم هدي أم لا؟","title":"حكم الهدي على المقيمين في مكة لأجل العمل","answer":"الجواب: هذا محل نظر؛ لأنهم غير مستوطنين؛ ولأنهم غير وافدين في وقت الحج، فهم بين هؤلاء وبين هؤلاء، الله سبحانه لما ذكر المتعة والهدي فيها، قال: ذَلِكَ لِمَنْ لَمْ يَكُنْ أَهْلُهُ حَاضِرِي الْمَسْجِدِ الْحَرَامِ [البقرة:196] ولهذا اختلف أهل العلم في مثل هذا، هل يعتبر مثل هذا من حاضري المسجد الحرام لأنه مقيم قبل العمرة وقبل الحج أم يعتبر أفقيًا لأنه ليس بمستوطن، وإنما أقام لحاجة، وسوف يرجع إلى بلاده؟  هذا موضع نظر واحتمال، والأحوط عندي، والأقرب عندي: أن مثله ليس من حاضري المسجد الحرام، في الحقيقة؛ لأنه إنما جلس لعارض، وأقام لعارض، من تدريس، أو طلب، أو عمل آخر، ثم يرجع إلى بلاده، فالأحوط له الهدي، وأن يعامل نفسه معاملة الوافدين للحج، هذا هو الأحوط. والقول بأنه من حاضري المسجد الحرام، وأنه يلحق بهم، قول قوي، لا يدفع، قول قوي جدًا، ولكن الأحوط في مثل هذا، والأقرب في هذا أنه يهدي، وأن جانب كونه أفقيًا، أقرب من جانب كونه من حاضري المسجد الحرام، نعم.","link":"https://binbaz.org.sa/fatwas/13533/حكم-الهدي-على-المقيمين-في-مكة-لاجل-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_653/nour_65307.mp3","categories":["الهدي والأضاحي"]},{"id":15411,"question":"سؤالها الثاني تقول: هل يؤثر على الإحرام مس المرأة أو مداعبتها فقط؟","title":"حكم مس المرأة أو مداعبتها حال الإحرام","answer":"الجواب: ليس للزوج أن يمسها بشهوة وهو محرم، ولا وهي محرمة، أما مسها من دون شهوة يمس يدها، يعطيها شيئًا، يأخذ منها شيئًا، من دون شهوة فلا حرج في ذلك، وهكذا مسها لزوجها، وهي محرمة، أو وهو محرم من دون شهوة لا يضر، ولا حرج في ذلك. المقدم: نعم، ماذا يترتب عليه على المس بشهوة؟ الشيخ: إذا مس بشهوة بعض أهل العلم يرى عليه فيها فدية، إما شاة، وإما إطعام ستة مساكين، وإما صوم ثلاثة أيام.\nالمقدم: على الاثنين معًا؟ الشيخ: عليهما جميعًا، إذا كانا محرمين، وإن كان أحدهما محرم والآخر ليس بمحرم على المحرم خاصة، إذا كان محرم مس بشهوة، فعليها فدية الأذى مخيرة، إما صوم ثلاثة أيام، وإما إطعام ستة مساكين، وإما ذبح شاة، هذا هو الذي ينبغي قياسًا على ما إذا حلق رأسه لعلة، نعم.","link":"https://binbaz.org.sa/fatwas/13918/حكم-مس-المراة-او-مداعبتها-حال-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68411.mp3","categories":["الهدي والأضاحي","الفدية وجزاء الصيد"]},{"id":15822,"question":"عبدالرزاق أحمد يقول: بالنسبة للذبح في الأضحية، أنا أذبح باليد اليسرى، خاصةً وأنا لا أجيد استعمال اليد اليمنى؟","title":"حكم ذبح الأضحية باليد اليسرى","answer":"الجواب: إذا ذبحت باليسرى الذبح الشرعي فلا بأس، والحمد لله. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14411/حكم-ذبح-الاضحية-باليد-اليسرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57514.mp3","categories":["الهدي والأضاحي"]},{"id":15907,"question":"أيهما أفضل في الأضحية: الكبش أو البقر؟","title":"أفضلية الأضحية بالغنم على البقر والإبل","answer":"الجواب: الكبش أفضل، الضحية بالغنم أفضل، وإذا ضحى بالبقر أو بالإبل فلا حرج، لكن النبي ﷺ كان يضحي بكبشين، وأهدى يوم حجة الوداع مائة من الإبل.  فالمقصود: أن الضحية بالغنم أفضل، ومن ضحى بالبقرة أو بالإبل -الناقة عن سبعة والبقرة عن سبعة- كله طيب.","link":"https://binbaz.org.sa/fatwas/14498/افضلية-الاضحية-بالغنم-على-البقر-والابل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57706.mp3","categories":["الهدي والأضاحي"]},{"id":15908,"question":"سماحة الشيخ، هل يجوز أن يعطى غير المسلم من لحم الأضحية؟","title":"حكم إعطاء الكافر من لحم الأضحية","answer":"الجواب: لا حرج أن يعطى؛ لقوله -جل وعلا-: لا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ [الممتحنة:8] فالكافر الذي ليس بيننا وبينه حرب، بل هو مستأمن أو معاهد يعطى من الضحية ومن الصدقة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14499/حكم-اعطاء-الكافر-من-لحم-الاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57707.mp3","categories":["الهدي والأضاحي"]},{"id":16167,"question":"تسأل سماحتكم وتقول: إذا لم يتم ذبح شاة، وأردت أن أتصدق بقيمتها، فهل ذلك جائز؟","title":"وجوب الهدي على المتمتع والقارن","answer":"الجواب:  الذبح في حق المتمتع أو القارن، أما الذي أحرم بالحج وحده إن أفرد الحج؛ فهذا ليس عليه ذبح، لكن الذي حج قارنًا بالحج والعمرة، أو أحرم بالعمرة، وفرغ منها، ثم أحرم بالحج؛ فهذا عليه دم،  ذبيحة واحدة يذبحها في منى أيام النحر: يوم العيد والثلاثة بعده، أو في وسط مكة؛ لا بأس، ويتصدق بها، أو يأكل منها، يتصدق ويأكل، ويطعم يأكل ويطعم، هذا يقال له: هدي التمتع ذبيحة واحدة، أو سبع بدنة، أو سبع بقرة. فإن عجز؛ صام عشرة أيام، ثلاثة أيام في الحج يعني: يصومها في الحج قبل يوم عرفة، وإن صامها في أيام منى في الحادي عشر، والثاني عشر، والثالث عشر أجزأ، لكن الأفضل أن يقدمها قبل عرفة، والسبعة إذا رجع إلى أهله، البقية السبعة الباقية تكون عند أهله أرفق به كما بين الله ذلك في كتابه العظيم، حيث قال سبحانه: فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ ذَلِكَ لِمَنْ لَمْ يَكُنْ أَهْلُهُ حَاضِرِي الْمَسْجِدِ الْحَرَامِ [البقرة:196] يعني: أن الذي من أهل مكة وهم حاضرو المسجد الحرام ليس عليهم هدي التمتع إذا كانوا من أهل مكة. المقدم: جزاكم الله خيرًا، نعيد الآية مرة أخرى لو تكرمتم سماحة الشيخ؟ الشيخ: يقول -جل وعلا-: فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ [البقرة:196] يعني: ما تيسر من الهدي، والمتيسر ذبيحة واحدة، أو سبع بدنة، أو سبع بقرة فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ [البقرة:196] يعني: إذا رجعتم إلى أهليكم. وهذا من تيسير الله ورحمته  ولهذا قال بعدها: تِلْكَ عَشَرَةٌ كَامِلَةٌ [البقرة:196] يعني: ثلاثة يأتي بها قبل الحج في مكة، وسبعة بعد رجوعه إلى أهله، فضلًا من الله -سبحانه- ورحمة منه -جل وعلا- وتيسيرًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14846/وجوب-الهدي-على-المتمتع-والقارن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_805/nour_80504.mp3","categories":["الهدي والأضاحي"]},{"id":16939,"question":"جزاكم الله خيرًا سماحة الشيخ، يقول السائل في ثاني أسئلته: والدي متوفى منذ أربع سنوات، ولكنه لم يحج، ولم يوص بالحج عنه؛ وذلك لأنه مات موتًا مفاجئًا، فما واجبنا، هل نحج عنه؟ علمًا بأنه لم يوصينا بذلك، وهل يجوز أن نقرأ له القرآن، وندفع مالًا على ذلك؟","title":"حكم الحج عن الميت وقراءة القرآن له","answer":"الجواب: إذا كان لم يحج، وخلف تركة؛ وجب أن يحج عنه من التركة إذا كان يستطيع الحج في حياته، ولكن تساهل وجب أن يخرج من ماله ما يحج به عنه، وإن حج عنه بعض أولاده كفى، أما إذا كان فقيرًا، مات ما يستطيع الحج، فإن أولاده إذا حجوا عنه مأجورون، لهم أجر إذا حج عنه بعض أولاده، أو إن حجت عنه زوجته، أو بعض أقاربه مأجورون، أما إذا كان لا، يستطيع الحج، عنده قدرة ولكن تساهل؛ فإنه يجب أن يخرج من ماله حجة، يعطاها الثقة حتى يحج بها عنه، وإن حج عنه بعض أولاده الطيبين كفى. المقدم: وبالنسبة لقراءة القرآن يقول يا سماحة الشيخ؟ الجواب: أما أن يقرأ على الميت، يقرأ القرآن على الميت هذا لا دليل عليه، ولا يشرع، ولكن يدعى له، أما قراءة القرآن للموتى هذا لا دليل عليه، ولا يشرع، لكن السنة أن يدعى للميت، يستغفر له، يترحم عليه، يتصدق عنه، يحج عنه، يعتمر عنه، كل هذا طيب.  أما أن يقرأ قرآنًا يثوبه له، هذا لا دليل عليه، أو يقرأ عند قبره هذا كله منكر، لكن إذا قرأ له في البيت، أو في المسجد ينويه له هذا لا دليل عليه، تركه أولى، ولكن يدعو له، يستغفر له، يترحم عليه، يتصدق عنه، يحج عنه، أو يعتمر عنه، نعم.","link":"https://binbaz.org.sa/fatwas/15713/حكم-الحج-عن-الميت-وقراءة-القران-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58612.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":16945,"question":"حدثونا عن كل فدية؟ وعن البديل عنها؟ وعن الهدي، والبديل عنه؟","title":"أحكام الهدي والفدية في الحج","answer":"الجواب: الهدايا والفدية في حق الحاج، والمعتمر متنوعة، فعلى من تمتع بالحج والعمرة، أو قرن بين الحج والعمرة عليه هدي، يسمى: هدي التمتع، وهذا فريضة، وهو شاة من الغنم تجزئ في الأضحية، سليمة من العيوب، تجزئ في الأضحية، شاة واحدة، رأس واحد من الغنم، أو سبع بدنة، أو سبع بقرة، في حق من تمتع بالعمرة إلى الحج، أو قرن بينهما ... والبديل عن ذلك صيام عشرة أيام، من عجز صام عشرة أيام، ثلاثة أيام في الحج، قبل عرفة، أو في أيام التشريق، وسبعة إذا رجع إلى أهله، هذا هو البديل. وهكذا من ترك واجبًا، إذا ترك الإحرام من الميقات، أو ترك الرمي -رمي الجمار- أو جمرةٍ من الجمار، كرمي جمرة العقبة، أو إحدى الجمار الثلاث؛ يكون عليه دم، ويجزئ عنه إذا عجز عنه صيام عشرة أيام، كما في هدي التمتع. وهكذا لو لبس المخيط وهو محرم، أو غطى رأسه، أو حلق رأسه، أو تطيب عمدًا، يكون عليه فدية مخيرة، وهي: صيام ثلاثة أيام، أو إطعام ستة مساكين، أو ذبح شاة، والإطعام ثلاثة أصواع، كل مسكين له نصف صاع من قوت البلد، من التمر، أو الأرز، أو الحنطة، والتفاصيل في الفدية معروفة في محلها، في كتب أهل العلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15740/احكام-الهدي-والفدية-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82805.mp3","categories":["الهدي والأضاحي"]},{"id":16963,"question":"حفظكم الله، البعض من الناس يقومون بذبح الأضحية في اليوم الثاني بعد يوم العيد، ولا يذبحونها في يوم النحر، ويقولون: بأن هذه هي السنة، وهم يداومون على هذه الحالة من زمان، وحتى الآن، لم يغيروا هذا، فهل هذا مجزئ؟","title":"البدار بذبح الأضحية أفضل من تأخيرها","answer":"الجواب:  الأفضل في يوم العيد، ثم الثاني، ثم الثالث، ثم الرابع، البدار بها في يوم العيد أفضل، ثم في الثاني أفضل من الثالث، ثم في الثالث أفضل من الرابع، أما تخصيص الثاني هذا غلط، جهل، بل الأفضل في الضحايا البدار بها يوم العيد، وهكذا الهدايا يوم العيد أفضل، فإن ذبحها في الثاني فهو أفضل من الثالث، وإذا ذبحها في الثالث فهو أفضل من الرابع، نعم.","link":"https://binbaz.org.sa/fatwas/15734/البدار-بذبح-الاضحية-افضل-من-تاخيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58618.mp3","categories":["الهدي والأضاحي"]},{"id":17068,"question":"يقول السائل: هل يلزم أهل الميت العيد له -أي: ذبح الأضحية- في عيد الأضحى له؟","title":"حكم التضحية عن الميت","answer":"الجواب: لا يلزمهم، لكن إذا ضحوا فهم مأجورون، من باب التطوع، كالصدقة عنه، وإلا فلا يلزمهم، إلا إذا أوصى بذلك، أوصى في بيت، أو مزرعة عليهم أن ينفذوا الوصية في الثلث فأقل. أما إذا كان ما أوصى فلا يلزمهم، لكن إذا تطوعوا ضحوا عنه، أو تصدقوا عنه فلهم أجر، لقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقةٍ جارية، أو علمٍ ينتفع به، أو ولدٍ صالح يدعو له «وسأله رجل قال: يا رسول الله! إن أمي ماتت، أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم. هذا يدل على أنه إذا تصدق عن أمه، أو أبيه، أو فلان، أو فلان له أجر. نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15873/حكم-التضحية-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58808.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":17132,"question":"من أسئلة السائل: عبده صالح سوري، أخوكم في الله يقول: هل الأضحية من الغنم تجوز عن جميع أهل البيت، أم عن نفر واحد؟","title":"إجزاء الأضحية عن جميع أهل البيت","answer":"الجواب: الأضحية تجزئ عن أهل البيت جميعًا، ولو كانوا مائة، إذا ذبح ضحية عنه، وعن زوجته، وأولاده، وأهل بيته كلهم؛ أجزأت، ولو شاةً واحدة، أو بقرةً واحدة، أو ناقةً واحدة، تجزئ؛ لأن الرسول ﷺ «كان يضحي بشاة واحدة عنه، وعن أهل بيته» اللهم صل عليه وسلم. نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15952/اجزاء-الاضحية-عن-جميع-اهل-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58923.mp3","categories":["الهدي والأضاحي"]},{"id":17603,"question":"يقول السائل من فلسطين السائل خالد حسين: بالنسبة يا سماحة الشيخ أنا أعيش مع إخواني ووالدي في منزل واحد، ويسكن معنا أخ لي متزوج وله أولاد، وسؤالي: هل الأضحية -أي: أضحية الوالد- تجزي عنا جميعًا، أم يجب على أخي المتزوج أضحيةً أخرى؟","title":"حكم أضحية واحدة على أهل البيت الواحد","answer":"الجواب: السنة تكفي الأضحية الواحدة من والدك؛ لأنكم في بيت واحد، فإذا ضحى والدك عنكم جميعًا؛ كفت والحمد لله، وهي سنة ما هي بواجبة سنة مؤكدة، فإذا ذبح والدك الضحية؛ أجزأت عنكم جميعًا أنتم وعن أخيك المتزوج أيضًا والحمد لله، كان الرسول يضحي بشاة واحدة عنه وعن أهل بيته. نعم.","link":"https://binbaz.org.sa/fatwas/16527/حكم-اضحية-واحدة-على-اهل-البيت-الواحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59411.mp3","categories":["الهدي والأضاحي"]},{"id":18120,"question":"هذا السائل (عبد الكريم . أ. أ) يقول: سماحة الشيخ! ما حكم الأضحية عن الميت؛ حيث إن البعض من الناس يقولون: بأن الأضحية عن الميت بدعة، فهي للأحياء وجهونا في ذلك؟","title":"هل الأضحية عن الميت بدعة؟","answer":"الجواب: الأضحية سنة عن الحي والميت، والذي يقول: إنها بدعة، قد غلط، والصواب أنها سنة عن الحي والميت، وقد ضحى النبي ﷺ بكبشين أحدهما عن محمد وآله وفيهم الميت كبناته، وضحى بكبش ثان عن من وحد الله من أمة محمد، وفيهم الحي والميت، فالضحية عن الميت قربة وطاعة كالحي، فإذا ضحى عن أبيه الميت، أو عن أمه الميتة، أو عن أخيه، أو زوجته؛ فكله قربة وكله طاعة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17162/هل-الاضحية-عن-الميت-بدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78109.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":18134,"question":"من ضمن أسئلة هذا السائل يقول سماحة الشيخ: أعيش أنا وزوجتي وأولادي في منطقة بعيدة عن سكن الوالد والوالدة وبقية أفراد الأسرة، إلا أننا في مناسبات الأعياد نتوجه إليهم لقضاء فترة العيد معهم، وفي عيد الأضحى المبارك نقوم بذبح أضحية واحدة للجميع فهل تكفي؟","title":"حكم الأضحية الواحدة عن أكثر من بيت","answer":"الجواب: السنة كل بيت يضحي، أنتم تضحون وأبوك يضحي، وهكذا البيوت الأخرى، إذا كان الإنسان في بيت مستقل يضحي عن نفسه وأهل بيته، هذا السنة .نعم. المقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/17168/حكم-الاضحية-الواحدة-عن-اكثر-من-بيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78111.mp3","categories":["الهدي والأضاحي"]},{"id":18150,"question":"أختنا تسأل وتقول: كيف يتم ذبح الأضحية في عيد الأضحى المبارك، ومتى يبدأ؟ ومتى ينتهي وقتها؟أرجو منكم أن تبينوا الطريقة التي نبدأ بها بالذبح، ماذا نعمل ونقول قبل الذبح وأثناءه وبعده؟ أي: إلى أن يتم توزيع اللحم إلى الفقراء؛ لأن طريقة الذبح عندنا هي: قبل الذبح يقرأ الملا القرآن على أذن الذبيحة، ويجب ألا يأكل صاحب الأضحية من اللحم إلا قطعة صغيرة، هل هذه الطريقة صحيحة؟ وهل يتم ذبح الأضحية للميت فقط؟ أم للحي؟ أم للاثنين؟ وفقكم الله.","title":"حكم الأضحية في عيد الأضحى وكيفيتها","answer":"الجواب: أما وقت الضحية فهو أربعة أيام على الصحيح من أقوال العلماء، يوم العيد وهو يوم عيد النحر وهو العاشر من ذي الحجة، ثم اليوم الحادي عشر، ثم اليوم الثاني عشر، ثم اليوم الثالث عشر، وقال بعض أهل العلم: إنها ثلاثة يوم العيد ويومان بعده، والصواب أنها أربعة: يوم العيد وثلاثة أيام من بعده، وهي أيام التشريق، وهي أيام النحر ،وهي أيام رمي الجمار، وهي أيام ذكر لله  وأكل وشرب. فإذا صلى الناس العيد صلاة العيد، بدءوا بالذبح، يبدءوا بالذبح بعد صلاة العيد، كما أمر النبي عليه الصلاة والسلام فإنه صلى ثم ذبح، وقال: من صلى صلاتنا ونسك نسكنا فقد أصاب النسك، ومن ذبح قبل الصلاة فلا ذبح له، فالسنة والواجب: أن تكون الضحية بعد الصلاة إذا كان الإنسان في البلد. أما إذا كان في الصحراء كالبادية فإنهم يذبحون بعد ارتفاع الشمس، إذا ارتفعت الشمس ومضى شيء بعد ارتفاعها بمقدار الصلاة، فإنهم يذبحون ذاك الوقت، يذبحون بعد ارتفاع الشمس ومضي قليل من الزمن بقدر الصلاة يذبحون؛ لأنهم لا صلاة عندهم، البادية هم مسافرون ليس لهم صلاة عيد، وليس عليهم صلاة عيد، فيذبحون بعد ارتفاع الشمس. وهكذا في منى -حجاج منى- يذبحون بعد ارتفاع الشمس؛ لأنه ليس عندهم صلاة عيد في منى، رمي الجمار يقوم مقام صلاة العيد، كما فعل النبي ﷺ، فإنه رمى الجمرة ثم نحر هديه ولم يصل صلاة العيد في حجة الوداع عليه الصلاة والسلام، فإنهم يرمون الجمار، ثم يذبحون هداياهم وضحاياهم بعد ذلك الوقت بعد ارتفاع الشمس، هذا هو المشروع. وعند الذبح يسمي الله يقول: باسم الله والله أكبر، هذا هو المشروع: باسم الله والله أكبر، وإن قال: باسم الله فقط أجزأ، ولكن الأفضل يقول: باسم الله والله أكبر، وإن زاد فقال: إن صلاتي ونسكي ومحياي ومماتي لله رب العالمين، لا شريك له وبذلك أمرت وأنا من المسلمين، أو قال: وجهت وجهي للذي فطر السماوات والأرض حنيفًا وما أنا من المشركين؛  فهذا مستحب، ولكن يكفي باسم الله والله أكبر، يكفيه هذا، هذا هو اللي كان يفعله النبي ﷺ باسم الله والله أكبر، وربما زاد: إن صلاتي.. إلى آخره، والواجب باسم الله، هذا الواجب، وزيادة: الله أكبر مستحبة، باسم الله والله أكبر، وما زاد على ذلك من قراءة: إن صلاتي، ووجهت وجهي.. هذا مستحب وليس بواجب. ثم إذا ذبحت الذبيحة يأكل الإنسان ما شاء ما يتقيد بقطعة صغيرة، بل يأكل ما شاء، إذا ذبحت الذبيحة يأكل منها قليلًا أو كثيرًا هو وأهل بيته، السنة: أن يأكلوا ويطعموا ويتصدقوا من هذه الذبيحة يأكلوا منها ما تيسر ويتصدقوا بما يتسر ويطعمون ويهدون ما تيسر، والأفضل أن تكون أثلاثًا: ثلث يأكلونه، وثلث يهدونه إلى أقاربهم وأصدقائهم وثلث للفقراء، وإن أكلوا الأكثر وتصدقوا بالقليل فلا بأس، الأمر في هذا واسع والحمد لله، الرسول ﷺ أمرهم أن يأكلوا ويطعموا، والله يقول: فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ الْفَقِيرَ [الحج:28]. فينبغي له أن يعطي الفقير ما تيسر من ذلك، وإن أعطوا الفقراء الثلث كان أفضل، وإن أهدى الثلث على أقربائه وجيرانه كان حسنًا أيضًا، فإن لم يهد ولم يتصدق إلا بالقليل أو ما تصدق بالكلية أجزأته الضحية، صارت الضحية مجزئة وشرعية، لكن ذهب بعض أهل العلم إلى أنه يجب عليه أن يخرج قليلًا من اللحم حتى يمتثل قوله تعالى: فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ الْفَقِيرَ [الحج:28]، يخرج ما تيسر من اللحم، ولو من غير الضحية إذا كان قد أكلها، يخرج من غيرها حتى يكون أدى هذا الواجب، ولكن السنة بكل حال أن يخرج منها، فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ فَكُلُوا مِنْهَا وَأَطْعِمُوا الْقَانِعَ وَالْمُعْتَرَّ [الحج:36]، كما قاله الله ، والنبي ﷺ قال: كلوا وتصدقوا وادخروا. فالسنة له أن يأكل وأن يدخر ما أحب من ذلك، وأن يتصدق على الفقراء ما تيسر، هذا هو المشروع، فإن لم يتصدق ولم يهد، بل أكلها صحت وأجزأت، ولكنه خالف الأفضل وخالف السنة، وعليه أن يستدرك ولو بالقليل من اللحم حتى يتصدق به على الفقراء هذا هو الأحوط له خروجًا من خلاف من قال بالوجوب وظاهر القرآن وجوب الصدقة؛ لأن الله قال: فَكُلُوا مِنْهَا وَأَطْعِمُوا ، والأصل في الأمر الوجوب، لكن ذهب الأكثرون إلى أنه للسنية؛ لأن الله قال: فَكُلُوا، والأكل ليس بواجب، فهكذا الإطعام ليس بواجب ولكنه سنة، السنة أن يأكل ويطعم، هذا هو السنة، نعم، والله المستعان.","link":"https://binbaz.org.sa/fatwas/17196/حكم-الاضحية-في-عيد-الاضحى-وكيفيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_853/nour_85303.mp3","categories":["الهدي والأضاحي"]},{"id":18172,"question":"يقول: لم أكن أملك ثمن هدي، فقمت بالصيام، أيام سبعة، وثمانية، وإحدى عشر من ذي الحجة، وبعد رجوعي قمت بصيام سبعة أيام متفرقة، في شهر ذي الحجة ومحرم، فهل علي شيء فيما تقدم؟ جزاكم الله خيرًا.","title":"ما حكم من صام عشرة أيام لعجزه عن الهدي؟","answer":"الجواب: لا شيء عليك إذا كنت عاجزًا عن الدم، الحمد لله، لكن الأفضل أن يكون الصيام قبل عرفة-الثلاثة- فإن لم يتيسر، ففي أيام منى -الحادي عشر، والثاني عشر، والثالث عشر- أما يوم عرفة؛ فالسنة فيه أن تكون مفطرًا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17212/ما-حكم-من-صام-عشرة-ايام-لعجزه-عن-الهدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73108.mp3","categories":["الهدي والأضاحي"]},{"id":18882,"question":"يسأل أخونا فيقول: هل يجوز أن تخصص الأضحية للميت فقط بعد وفاته، حيث أن كثيرًا من العوام أصبح لزامًا عليهم إذا توفي والده أو والدته أو أخوه؛ نحر له ناقة في أول عيد للأضاحي بعد وفاته مباشرة، فهل يجوز ذلك؟ وما هو الجائز في الأضحية؟ وما هي الأضحية؟ وهل هي من الإبل أم من البقر أم من الغنم؟ وأيها أفضل؟جزاكم الله خيرًا.","title":"هل يجوز أن تخصص الأضحية للميت فقط بعد وفاته؟","answer":"الجواب: الأضحية سنة عن الحي والميت، النبي ﷺ كان يضحي بشاة واحدة عنه وعن أهل بيته، أحيائهم وأمواتهم، وإذا ضحى بناقة ببعير، ببقرة، فلا بأس. أما اعتقاد أنه يضحى عنه بجمل، أو ببقرة أول سنة هذا لا أصل له، السنة أن يضحي بما تيسر، سواءً كان ببقرة أو بناقة أو من الغنم، الحمد لله، وإن جمع أهل بيته بواحدة كفى، لو ذبح شاة واحدة عنه وعن أهل بيته: زوجاته وأولاده أحيائهم وأمواتهم فلا بأس، وإن جمعهم في بقرة أو في ناقة فلا بأس، الأمر واسع، بحمد الله، نعم. المقدم: جزاكم الله خيرًا، يسأل سماحتكم سماحة الشيخ ويقول: هل الأضحية في كل عام أو مرة في العمر؟ الشيخ: السنة في كل عام، الضحية كل عام، كان النبي يضحي كل عام -عليه الصلاة والسلام- عنه وعن أهل بيته شاة واحدة، اللهم صل عليه وسلم، نعم. ويضحي عن أمة محمد بشاة ثانية. كان يضحي بشاتين بكبشين:\nأحدهما: عنه وعن أهل بيته.\nوالثاني: عمن وحد الله من أمة محمد -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18020/هل-يجوز-ان-تخصص-الاضحية-للميت-فقط-بعد-وفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73615.mp3","categories":["الهدي والأضاحي"]},{"id":18918,"question":"هذا سائل للبرنامج سماحة الشيخ يقول: هل الهدي له علاقة بالتحلل الأول أو الثاني؟","title":"علاقة الهدي بالتحلل الأول أو الثاني","answer":"الجواب: هدي التمتع ليس له تعلق، التحلل يتعلق بالرمي والحلق أو التقصير والطواف والسعي فقط، دم الهدي ما له تعلق.","link":"https://binbaz.org.sa/fatwas/18087/علاقة-الهدي-بالتحلل-الاول-او-الثاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88217.mp3","categories":["الهدي والأضاحي"]},{"id":19042,"question":"هل الأضحية -يا سماحة الشيخ- هل الأضحية أفضل للحي أو للميت، وهل يشتركون سواء؟","title":"هل الأضحية أفضل للحي أم للميت، أم هما سواء؟","answer":"الجواب: الأضحية سنة عن الحي والميت عنه وعن أهل بيته أحياء وأموات، كان النبي ﷺ يضحي عن أهل بيته أحيائهم وأمواتهم، كان يضحي بكبشين؛ أحدهما عن محمد وآل محمد، والثاني عمن وحد الله من أمة محمد عليه الصلاة والسلام، فإذا ضحى الإنسان عنه وعن أهل بيته والديه وزوجاته وأولاده كفى واحدة، وإن ضحى بأكثر فلا بأس. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/18211/هل-الاضحية-افضل-للحي-ام-للميت-ام-هما-سواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88309.mp3","categories":["الهدي والأضاحي"]},{"id":19043,"question":"هل يجوز التلفظ بالنية عند ذبح الأضحية والهدي؟","title":"حكم التلفظ بالنية عند ذبح الأضحية والهدي","answer":"الجواب: المشروع أن يتلفظ، ويقول: اللهم إنها منك ولك هذه كذا.. ضحية عن فلان مثلما كان النبي ﷺ يتلفظ وهكذا في الهدية، يقول: باسم الله والله أكبر، وإذا سمى فلا بأس، سمى هدية عن فلان وإلا يكفي النية، يقول: باسم الله والله أكبر، وإن قرأ: إِنَّ صَلاتِي وَنُسُكِي .... [الأنعام:162]، إلى آخره لا بأس، وإن قال: اللهم تقبل من فلان فلا بأس كما فعله النبي ﷺ لكن لابد من التسمية باسم الله، والأفضل أن يقول معها: والله أكبر؛ باسم الله والله أكبر. أما الضحية فيقول: عن فلان، مثلما قال ﷺ: عن محمد وآل محمد، في الضحية، أما الهدي يكفي النية في الهدي كونه هدي تمتع أو قران، أو عن ترك واجب أو فعل محظور، يكفي النية ويقول: باسم الله والله أكبر.","link":"https://binbaz.org.sa/fatwas/18210/حكم-التلفظ-بالنية-عند-ذبح-الاضحية-والهدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88308.mp3","categories":["الهدي والأضاحي"]},{"id":19044,"question":"هذا السائل يا سماحة الشيخ يقول: سماحة الشيخ! حفظكم الله، ما الشروط التي يجب أن تتوفر في الهدي، وأيضًا ما الشروط التي يجب أن تتوفر في الأضحية؟","title":"الشروط الواجب توافرها في الأضحية والهدي","answer":"الجواب: لابد أن تكون سليمة من العيوب، مثلما قال ﷺ: أربع لا تجزئ في الأضاحي: العوراء البين عورها، والمريضة البين مرضها، والعرجاء البين ضلعها، والهزيلة التي لا تنقي . ونهى أن يضحى بأعضب القرن والأذن، الذي ذهب أكثر قرنه أو أذنه لابد يراعى فيها سلامتها من العيوب سواء كانت ضحية أو هدية. نعم.","link":"https://binbaz.org.sa/fatwas/18208/الشروط-الواجب-توافرها-في-الاضحية-والهدي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88307.mp3","categories":["الهدي والأضاحي"]},{"id":19155,"question":"يقول أخونا في سؤال آخر: نحن عائلة ولم يقسم بيننا الوالد، ونعيش في بيت واحد، واثنان منا يأخذون مرتب، ولكننا في عيد الأضحى لا نضحي إلا بأضحية واحدة، فهل تجزئ عنا جميعًا؟","title":"هل تجزئ الأضحية الواحدة عن العائلة؟","answer":"الجواب: نعم إذا كنتم في بيت واحد مشتركين في السكن، وأكلكم واحد، وطعامكم واحد، يكفيكم الضحية الواحدة، أما إذا كان البيت شققًا مختلفة، كل ناس في شقة مستقلين بأنفسهم، فالسنة لكل أهل شقة، أو لكل أهل دور من الأدوار أن يضحوا عن أنفسهم، هذا هو السنة. أما إذا كنتم مجتمعين حالكم واحد، وطعامكم واحد ومشتركين في بيت سواء دور أو أدوار، فالضحية الواحدة تكفي، وإن ضحيتم بأكثر فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18330/هل-تجزى-الاضحية-الواحدة-عن-العاىلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93203.mp3","categories":["الهدي والأضاحي"]},{"id":19157,"question":"يقول أخونا في سؤال آخر: نحن عائلة ولم يقسم بيننا الوالد، ونعيش في بيت واحد، واثنان منا يأخذون مرتب، ولكننا في عيد الأضحى لا نضحي إلا بأضحية واحدة، فهل تجزئ عنا جميعًا؟","title":"هل تجزئ الأضحية الواحدة عن العائلة؟","answer":"الجواب: نعم إذا كنتم في بيت واحد مشتركين في السكن، وأكلكم واحد، وطعامكم واحد، يكفيكم الضحية الواحدة، أما إذا كان البيت شققًا مختلفة، كل ناس في شقة مستقلين بأنفسهم، فالسنة لكل أهل شقة، أو لكل أهل دور من الأدوار أن يضحوا عن أنفسهم، هذا هو السنة. أما إذا كنتم مجتمعين حالكم واحد، وطعامكم واحد ومشتركين في بيت سواء دور أو أدوار، فالضحية الواحدة تكفي، وإن ضحيتم بأكثر فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18331/هل-تجزى-الاضحية-الواحدة-عن-العاىلة","audio":"","categories":["الهدي والأضاحي"]},{"id":19597,"question":"يقول هذا السائل يا سماحة الشيخ: إذا استدان الشخص ليضحي، فما حكم ذلك؟","title":"حكم الاستدانة من أجل الأضحية","answer":"الجواب: لا بأس، لا حرج، إذا كان له وفاء، إذا كان عنده أسباب يوفي منها لا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/18856/حكم-الاستدانة-من-اجل-الاضحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94911.mp3","categories":["الهدي والأضاحي"]},{"id":19599,"question":"يقول السائل يا سماحة الشيخ: أيهما أفضل الكبش أم البقر في الأضحية؟","title":"أفضل أنواع الأضاحي","answer":"الجواب: الغنم أفضل، الغنم أفضل في الأضحية، وإن ضحى ببقر أو غنم أو إبل فلا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18860/افضل-انواع-الاضاحي","audio":"","categories":["الهدي والأضاحي"]},{"id":19602,"question":"هذا سائل للبرنامج -أبو يوسف- يقول: سماحة الشيخ لم أذبح شاتين عندما رزقت بمولود، بل شاة واحدة، وبقيمة الشاة الثانية اشتريت دجاجًا، وقمت بتوزيعها على الفقراء، هل هذا جائز؟","title":"حكم العقيقة بشاة واحد وتوزيع دجاج على الفقراء بقيمة الأخرى","answer":"الجواب: هذا ما يكفي، السنة ثنتان في حق الرجل، فالمستحب لك أن تذبح شاة أخرى، والدجاج ما يكفي، ولكن يستحب لك أن تشتري أخرى تذبحها ولو بعد مضي سنة أو سنتين؛ لأن السنة في حق الغلام شاتان ذبيحتان، وفي حق الجارية واحدة.نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18873/حكم-العقيقة-بشاة-واحد-وتوزيع-دجاج-على-الفقراء-بقيمة-الاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94809.mp3","categories":["الهدي والأضاحي"]},{"id":19603,"question":"ما حكم الأضحية عن الأموات يا شيخ؟","title":"ما حكم الأضحية عن الأموات؟","answer":"الجواب: إذا ضحى لا أرى فيه حرجًا، وإذا ضحى عن نفسه وأهل بيته الحي والميت فلا بأس، النبي ﷺ كان يضحي بكبشين، أحدهما عنه وعن أهل بيته، والثاني عمن وحد الله من أمته عليه الصلاة والسلام، فإذا ذبح الإنسان ضحية عنه وعن أهل بيته من زوجة وأولاد ووالدين فلا بأس بذلك. نعم.","link":"https://binbaz.org.sa/fatwas/18858/ما-حكم-الاضحية-عن-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94912.mp3","categories":["الهدي والأضاحي","إهداء القرب للميت"]},{"id":19652,"question":"هذا سائل يقول يا سماحة الشيخ: بالنسبة لمن ذبح الأضحية قبل صلاة العيد؟","title":"حكم ذبح الأضحية قبل صلاة العيد","answer":"الجواب: لا تجزئ إلا بعد الصلاة، النبي ﷺ قال: من ذبح قبل أن يصلي فهي شاة لحم لا تجزئ، لابد أن تكون بعد الصلاة. نعم.","link":"https://binbaz.org.sa/fatwas/18936/حكم-ذبح-الاضحية-قبل-صلاة-العيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95006.mp3","categories":["الهدي والأضاحي"]},{"id":19653,"question":"ماذا يعمل الرجل والمرأة إذا أراد أن يذبح الأضحية أيام ذي الحجة، هل يمسك عن شعره وأظفاره؟","title":"الواجب على من أراد أن يضحي","answer":"الجواب: نعم، هذا الواجب، من أراد أن يضحي لا يأخذ من شعره ولا من أظفاره، إذا كان يضحي عن نفسه أو عن والديه ونفسه، أما إذا كان الوكيلًا لا، إذا كان وكيل في الأوقاف والضحايا لا ما عليه شيء، لكن إذا كان يضحي عن نفسه من ماله، يضحي عن أبيه أو عن أمه أو عن نفسه أو عنه وعن أهل بيته يمسك عن شعره وأظفاره، إذا دخل الشهر، شهر ذي الحجة حتى يضحي؛ لقول النبي ﷺ: إذا دخل شهر ذي الحجة وأراد أحدكم أن يضحي فلا يأخذ من شعره ولا من أظفاره شيئًا، هكذا نهى ﷺ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18937/الواجب-على-من-اراد-ان-يضحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95007.mp3","categories":["الهدي والأضاحي"]},{"id":19680,"question":"سماحة الشيخ، هذا سائل يقول: بالنسبة للأضحية الواحدة هل تكفي للعائلة الكبيرة في البيت الواحد؟","title":"حكم الضحية الواحدة عن البيت الواحد ولو كثروا","answer":"الجواب: نعم تكفيهم أضحية واحدة، كان الرجل يضحي في عهد النبي ﷺ بالشاة الواحدة عنه وعن أهل بيته، كما ذكر أبو أيوب ، والنبي ﷺ ضحى بشاة واحدة عنه وعن أهل بيته صل عليه وسلم ولو كانوا مائة. نعم.\nالمقدم: الحمد لله، جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/18972/حكم-الضحية-الواحدة-عن-البيت-الواحد-ولو-كثروا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95033.mp3","categories":["الهدي والأضاحي"]},{"id":19681,"question":"يا سماحة الشيخ أيضًا هل يجزي أن ندفع مبلغًا من المال لشراء أضحية وذبح ذلك في الخارج للفقراء والمساكين؟","title":"حكم دفع مال لشراء أضحية وذبحها في الخارج للفقراء","answer":"الجواب: لا حرج سواء ذبحها في بيته أو في الخارج، لكن في بيته أفضل، إذا ضحى في بيته وأكل منها ووزع على من حوله كان أفضل تأسيًا بالنبي ﷺ كونه يذبح الضحية في بيته ويأكل ويطعم، وإذا أحب أن يذبح ضحايا أخرى في محل فقراء في بلد أخرى فله أجر ذلك؛ لأن هذا من الصدقات. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18973/حكم-دفع-مال-لشراء-اضحية-وذبحها-في-الخارج-للفقراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95034.mp3","categories":["الهدي والأضاحي"]}]
